GLOSSARY={
'变量':('给一个值起的名字。','minutes = 20 就是把20交给名字minutes保管；以后读minutes，就取出20。名字不是另一个数字。'),
'赋值':('计算右边，再把结果交给左边的名字。','x = x + 1 先取出旧x，加1，再存回x。数学等式要求两边相等，Python的=却是在执行一次操作。'),
'字符串':('被引号包住的文字。','"20"是文字，20是数字。"20"+"5"得到"205"，20+5得到25。引号本身通常不显示在print结果里。'),
'列表':('按顺序放置多个值的容器。','[10,20,30]有3项。方括号表示列表，逗号分隔不同项；列表里的值可以逐个访问。'),
'索引':('某一项的位置编号。','Python从0编号：[10,20,30]中编号0对应10，编号1对应20。-1表示最后一项，不是把值减1。'),
'循环':('让同一组指令对多个输入重复执行。','for x in [2,4]会先让x等于2，执行缩进的代码，再让x等于4，再执行一次。'),
'函数':('把一组操作装进一个有名字的小工具。','def double(x): return x*2定义工具；double(3)才真正使用工具，结果是6。'),
'参数':('函数或模型中需要使用的量，具体含义看语境。','double(x)里的x是函数参数；模型y=wx+b里的w和b是模型参数。二者不要混为同一个概念。'),
'返回值':('函数计算后交还给调用者的结果。','return 6把6交出去；print(6)只显示6。没有return的函数通常返回None。'),
'缩进':('代码行开头的空格，用来表示归属关系。','if、for、def后的下一组代码通常缩进4格。缩进不是排版装饰，它会改变程序的行为。'),
'字典':('用名字或键查找对应值的容器。','{"AI":30}表示键"AI"对应值30。取record["AI"]相当于问“AI这一项存了什么”。'),
'布尔值':('只表示是或否的值。','True表示成立，False表示不成立。3>2得到True，3<2得到False。'),
'平方':('一个数与它自己相乘。','3²=3×3=9。Python写3**2；**是乘方，不是普通乘号*。'),
'平方根':('反过来寻找“哪个非负数的平方等于它”。','√9=3，因为3×3=9。math.sqrt(9)得到3.0；sqrt是square root的缩写。'),
'求和':('把一组数逐个加起来。','Σ是希腊字母sigma，常写作求和符号。Σxᵢ在[2,3,4]上就是2+3+4=9；sum执行同样操作。'),
'平均值':('总和除以数量，让每一项获得同样份额。','[2,4,6]的平均=(2+4+6)÷3=4。平均数不一定是原列表里出现过的值。'),
'比例':('一部分占总体的多少。','2个命中、共5个，比例2÷5=0.4，也就是40%。小数0.4和百分数40%表示同一比例。'),
'绝对值':('去掉正负方向，只看离0多远。','|−3|=3，|3|=3。Python用abs(-3)；绝对值不能说明原来是正方向还是负方向。'),
'向量':('有顺序的一组数，用于共同描述一个对象。','[3,4]可以表示“向右3格、向上4格”，也可以表示两项特征。要先说清每个位置代表什么。'),
'维度':('有多少个分量，或数组有多少根轴，需结合语境。','二维向量[3,4]有2个分量；2×3表格有行和列两根轴。两种“维度”的说法容易混淆。'),
'矩阵':('按行和列排列的数表。','[[1,2],[3,4]]有2行2列。行是横着的一排，列是竖着的一排；2×3表示2行、每行3个数。'),
'点积':('同位置相乘，再把乘积加起来。','[1,2]·[3,4]=1×3+2×4=11。先配对，不是把两个列表直接拼接。'),
'范数':('按约定衡量一组数整体有多大。','[3,4]的L2范数是√(3²+4²)=5，可理解为二维箭头长度。L1范数则是|3|+|4|=7。'),
'下标':('写在字母右下方的编号，不是乘法。','x₁、x₂表示第1、2个分量。数学常从1编号，Python列表却从0编号，换写时要留意。'),
'概率':('在给定条件和模型下，对事件发生可能性的刻画。','概率0表示不可能，1表示必然。公平硬币正面概率0.5；现实中的估计概率有不确定性。'),
'条件概率':('已经知道一件事发生后，重新看另一件事的可能性。','P(A|B)读作“在B发生的条件下A的概率”。竖线不是除号；必须先说B是什么。'),
'期望':('按每种结果的概率加权后的平均。','得0分和10分各一半概率，期望=0×0.5+10×0.5=5，不意味着下一次一定得到5分。'),
'方差':('每个值离平均值多远，先平方再求平均。','[1,3]均值2，偏离为-1、1，方差=(1+1)÷2=1。平方避免正负误差相互抵消。'),
'标准差':('方差的平方根，单位回到原始量。','方差4时标准差2。用它描述波动时，比“平方单位”的方差更容易和原数据比较。'),
'导数':('输入变化很小时，输出变化速度的刻画。','直线y=2x的导数是2：x增加一点，y大约增加其2倍。曲线上不同位置的变化速度可以不同。'),
'梯度':('把多个参数各自的变化率排成一组数。','损失依赖w和b时，梯度说明分别改动w、b会怎样影响损失。它不是损失数值本身。'),
'学习率':('每次更新参数时迈多大一步。','更新w←w−0.1×梯度中0.1就是学习率。不是“学会的百分比”，也不是准确率。'),
'模型':('一套把输入变成输出的计算规则。','模型ŷ=2x+1接收x=3，输出7。模型可以很简单，不一定是神经网络。'),
'样本':('数据中的一个观察对象。','一行房屋信息是一个样本，一张图片也可作为一个样本。先约定一条样本的边界。'),
'特征':('预测时给模型看的输入信息。','预测房价时面积可以是特征。房子最终卖了多少钱是目标，不能提前当输入偷看。'),
'标签':('训练时希望模型学会预测的目标答案。','“这张图片是猫”中的猫是标签。无监督任务没有这样的已知目标类别。'),
'预测':('用当前模型计算一个输出。','用ŷ=2x+1代入x=3得到7，叫预测。预测可能错误，必须与真实目标比较。'),
'损失':('把预测的好坏变成可计算的数。','真实5、预测7，平方损失=(7−5)²=4。这个4不是“错了4个样本”，而是所选误差定义的值。'),
'训练':('用数据不断比较预测与目标，再更新模型参数。','不是把代码运行一次就一定发生训练。只有确实根据目标调整参数，才在这个语境下叫训练。'),
'验证集':('训练之外、用于选择设置的数据。','可以比较不同学习率在验证集的表现。因为用来挑方案，它不再是完全独立的最终考试。'),
'测试集':('留到最终评估的数据。','像期末考试：反复看考试答案调模型，会让考试失去检验新问题能力的意义。'),
'过拟合':('记住训练细节，却不能很好处理新样本。','像背会练习册答案却不会做换数字的新题。训练分数高、独立测试表现差是常见信号。'),
'归一化':('按指定规则重新调整数值尺度。','把[0,10]范围映到[0,1]可用除以10。具体规则有很多，必须说明采用哪一种。'),
'对数':('乘方的反方向：问“底数要乘方几次”。','2³=8，所以log₂8=3。math.log使用自然对数，底数是约2.718的e。'),
'指数':('底数按某个数乘方。','exp(2)表示e²，不是2×e。机器学习常用指数把实数得分转成正数，但大数可能溢出。'),
'权重':('决定某一输入对结果贡献多少的系数。','y=2×面积+1中2是面积的权重；改变2会改变所有面积对应的预测。'),
'偏置':('不随当前输入改变的额外加数。','y=2x+1中的1是偏置，允许x=0时预测也不必为0。'),
'神经网络':('多层“加权求和，再做非线性变换”的组合。','它是数学计算结构，不需要把它理解为真的大脑。每一层的输入输出形状都可以检查。'),
'激活函数':('加权求和之后，再按规则改变数值。','ReLU把负数变成0、正数保留。没有非线性时，多层线性运算仍能合并成一层。'),
'token':('由某个分词器定义的文字处理单元。','可能是一个字、词的一部分或特殊符号。不同分词器结果不同，不能直接等同于字数。'),
'嵌入':('把离散对象映射为一组可计算的数字。','一个词可对应[0.2,−0.1,0.7]。数字坐标本身没有通用自然语言含义，要看它怎样训练出来。'),
'注意力':('按匹配程度给若干信息分配权重，再加权汇总。','若两个值10、20的权重为0.7、0.3，汇总=10×0.7+20×0.3=13。这不是人的意识。'),
'排序':('按照某个分数决定先看哪个。','分数[0.2,0.9,0.4]中0.9最大，因此对应候选排最前。分数不一定是概率。'),
'阈值':('把连续数值转换为动作时采用的分界。','概率≥0.5预测为正类。换成0.8会改变决策，但不会改变模型之前算出的概率。'),
'批次':('一次一起处理的小组样本。','10个样本、每批4个，依次可分成4、4、2。最后一批未必和其他批一样大。'),
'迭代':('按照相同规则反复改进当前结果。','从w=0开始更新一次，再拿更新后的w继续算下一次。它不是每轮都重新回到0。'),
'集合':('用于记录不同元素、不重复保留的容器。','set([1,1,2])只保留1和2。集合一般没有可依赖的位置顺序。'),
'均方误差':('先逐项算预测误差的平方，再求平均。','预测[2,4]、目标[1,6]，误差[1,−2]，平方[1,4]，平均2.5。'),
'精确率':('被预测为正类的样本中，有多少真的为正。','找出10封垃圾邮件，其中8封真是垃圾，精确率8/10=80%。'),
'召回率':('所有真正的正类中，有多少被找了出来。','实际有20封垃圾邮件，找对8封，召回率8/20=40%。与精确率的分母不同。'),
'候选':('还没有最终决定、待比较的可能结果。','检索先找10段可能相关文字，再挑最相关的3段。候选并不自动等于正确答案。'),
'检索':('从已有资料中按规则寻找相关内容。','检索返回的是文档或片段；生成回答是另一个步骤。找到资料不代表资料一定正确。'),
'轨迹':('按时间记录的一串状态、动作和结果。','游戏里每一步在哪里、选了什么、得了几分，连在一起就是一条轨迹。'),
'缓存':('保存可以重复利用的计算结果。','相同输入不必每次从头计算。模型版本变了，旧缓存可能不再适用。'),
}

CONTEXT={}
def context(key,story,core,method,terms,visual='pipeline'):
    CONTEXT[key]=dict(story=story,core=core,method=method,terms=terms.split('|'),visual=visual)

context('python-0','想象你有一位很认真、但完全不会猜意思的助手。你说“帮我算一下”，它不知道算什么；你说“把20乘以60，再显示结果”，它就有明确步骤。编程是在学习怎样把想法说成计算机能够精确执行的指令。','先不用记住很多英文。把程序看成从上到下的一张操作清单：读到一行，按规则完成这一行，再往下走。文字需要引号，算术符号直接计算。某行出错时，后面的指令通常不会继续执行。','第一次练习分三遍：先不运行，用纸猜输出；再运行对照；最后只改一个数字或一段文字。一次改太多地方，出错后很难判断是哪一处造成的。','变量|赋值|字符串|函数|返回值','memory')
context('python-1','你准备出门：下雨就带伞，没有下雨就不带。你检查购物清单：每个商品都算一次价格。这两件日常小事，分别对应“条件判断”和“循环”。','条件回答“这次做不做”，循环回答“同一组操作重复几次”。看代码时先圈出冒号和缩进：冒号下面缩进去的行属于这个判断或循环，退回原位置的行表示已经走出这一组。','不要同时追踪所有变量。先在纸上写一张小表：第几次、当前值、判断结果、输出或累计值。每次循环填一行，重复执行就变得看得见。','布尔值|循环|缩进|变量|赋值','flow')
context('python-2','一个学习记录可能包含很多天的数据。只用一个变量会反复覆盖旧值，于是需要“能放很多东西的容器”：有顺序的列表、按名字查找的字典、只保留不同元素的集合。','先决定容器里“一项”是什么，再决定如何取用。列表像编号抽屉，字典像“姓名→电话号码”的通讯录，集合像不重复的签到名单。它们解决的问题不同，不是几个可随意互换的括号。','每次操作都问三件事：原容器是否被修改？是否产生新的值？结果的类型是什么？尤其要区分“修改原物”和“返回新结果”，否则很容易把原变量赋成None。','列表|索引|字典|集合|返回值','containers')
context('python-3','如果每天都要把分钟换成秒，你不想把同样的三行抄几十遍。把步骤放进一个工具、给工具起名字，以后传入不同分钟数就能使用，这就是函数。','定义工具和使用工具是两个时刻。def先描述工具怎么工作，调用时才传入数据。函数内部的临时名字通常只在内部有效，想让外部拿到计算结果，需要return。','先给函数一个最简单的正确输入，再检查特殊输入。遇到报错先看最后一行的错误类别，再找对应行；修一处就重跑，不要凭感觉同时乱改很多地方。','函数|参数|返回值|变量|缩进','pipeline')
context('python-4','纸上的笔记关掉以后还在，但程序中的变量通常在程序结束后就消失。文件相当于把结果写到一个可以以后再打开的本子里；JSON则约定了记录的写法，让其他程序也能读懂。','先分清“Python中的对象”和“保存时的文字”。字典可以包含多个键值；保存成JSON后是按格式组织的文本。重新读取需要解析，不能把文件里的字符当成已经恢复的字典。','本网站中的文件在浏览器临时文件系统里。先使用样例文件练习读取与写入，再学习本机路径和备份；不要一开始就对自己的重要文件做覆盖操作。','字典|字符串|变量|函数|返回值','file')
context('ai-map','“预测明天是否下雨”和“按固定税率算金额”都能交给计算机，但需要的方法不同。学习AI之前，最有用的第一步不是下载最大的模型，而是把要解决的问题说清楚。','把每个任务拆成四格：给程序什么、希望它回答什么、从哪里知道答案、怎样判断做得好。AI不是一个自动解决所有问题的按钮，而是一组有条件、有成本的方法。','先设计一个不用复杂模型也能运行的简单方案，称为基线。以后换算法，都在同一批独立样例上比较，否则“看起来更厉害”很可能只是问题变了。','模型|样本|特征|标签|训练|测试集','pipeline')
context('python-ai','当程序从几行长到几百行时，真正困难的是让人还能读懂。推导式、函数、类和批处理不是为了把代码写得神秘，而是把重复步骤组织清楚。','先问数据是什么，再问如何组织操作。类把参数和方法放到一起；生成器让数据一批批产生。它们不改变数学答案，但影响代码是否容易复用、检查和节约内存。','读到简写时先展开成普通for循环；读到对象时列出它存了哪些属性；读到生成器时手工取前两批。能展开解释后，再使用简写。','函数|参数|返回值|循环|批次|列表','pipeline')
context('linear-algebra','假设你描述一间房子：面积80平方米、楼层3、距地铁1公里。这三个数字按固定顺序放在一起，就能作为一组特征。很多房子的记录整齐排成行，便得到一张数表。','线性代数研究的是这种“数字组”和“数表”如何组合、变换。先不用害怕字母：字母是数字的名字，下标是编号，括号决定哪些数在同一组。所有公式都可以先换成两三个具体数字。','每道题先写形状和位置含义，再按“配对→计算→检查”完成。数学中的第1项对应Python索引0，先把编号对齐，再做乘法或求和。','向量|矩阵|维度|下标|点积|求和|范数','vectors')
context('calculus','骑车时，你既关心已经走了多远，也关心“现在快不快”。微积分把“累计了多少”和“此刻变化多快”变成可以计算的对象。训练模型时，我们最关心怎样改参数能让错误减少。','导数不是凭空冒出的特殊数字，而是比较一次很小的输入变化与输出变化：输出改变量÷输入改变量。参数有多个时，每个参数都可以单独问这个问题，得到一组变化率，叫梯度。','先用一元函数代数字，再看曲线上的位置和方向，最后学习符号。更新参数时，先算这一步的梯度，再改参数；下一步一定用更新后的参数重新算。','导数|梯度|学习率|损失|参数|平方','slope')
context('probability','你想知道一个活动成功的可能性，但一次成功不能说明以后次次成功。概率帮助描述不确定性，统计则帮助从有限记录估计总体情况，并说明估计可能有多不稳定。','始终区分“某次发生了什么”和“很多次可能呈现怎样的规律”。平均值不是每次都会出现的结果；观察到某个比例，也不意味着真实概率被完全确定了。','先用具体人数或次数做一张频数表，再改写成小数和公式。分母到底是谁非常重要：全部人、被检测为阳性的人、真实正类的人，可能是完全不同的群体。','概率|条件概率|比例|平均值|期望|方差|标准差','probability')
context('information','如果你早就知道盒子里一定是红球，打开盒子没有多少新信息；如果两种颜色各一半，结果就更难提前确定。信息论把这种“不确定”变成可计算的量。','分类模型输出的是对多个结果的概率分配。我们不仅问猜对没猜对，还问：它给正确结果分配了多少概率？一个很自信的错误，往往比犹豫的错误受到更大惩罚。','遇到log、exp先看下面的术语解释。不要一上来背复杂式子，先比较“正确类概率0.8”和“正确类概率0.2”哪一种应该损失更小，再计算验证。','概率|对数|指数|损失|归一化|求和','distribution')
context('data-tools','模型像厨房里的厨师，原始数据像刚买来的食材。食材可能缺斤少两、切法不一、混进错误标签。还没把数据整理清楚就训练，往往只是更快地把问题放大。','数组解决“整齐的一批数字如何计算”，表格解决“每列什么意思、每行对应谁”。缺失值不一定是0，文字数字也不是数值。看数据之前，先把列名、类型、单位和样本定义写清楚。','从五行小数据开始：打印内容、数行数、检查缺失、手算一项统计，再用程序验证。浏览器例子故意不用外部包，让你先看懂原理；框架接口是下一步。','样本|特征|矩阵|列表|字典|平均值','table')
context('features','假设你教人根据面积猜房价，却把最终成交价也放进提示里，练习分数会漂亮得不真实。特征工程首先要确认：预测那一刻，这些信息真的能拿到吗？','训练、验证、测试像练习、模拟考、期末考试。任何从数据学出的处理规则，例如填补均值或缩放尺度，都只能先从训练数据确定，再原样用于后面的数据。','先把数据划分好，再做会学习统计量的预处理。每一步保留字段含义和变换规则；做完后检查输入的形状、范围和缺失情况，而不是直接按下训练按钮。','特征|标签|训练|验证集|测试集|归一化','split')
context('supervised','老师给你一些“题目和答案”，希望你以后遇到新题也能做对。监督学习也是这样：样本带着目标答案，模型通过比较自己的预测与目标来调整。','模型首先是一条明确的计算规则。线性回归用加权求和；树通过问题分支；近邻参考相似样本。名称不同，但都需要说明输入、输出、学习过程和检验方法。','按同一顺序学习每个算法：拿一组很小的数据→手算一个预测→理解错在哪里→看怎样调整→用新数据检查。先把一个样本讲清楚，再谈大规模训练。','模型|样本|特征|标签|预测|权重|偏置|损失','prediction')
context('unsupervised','你拿到一箱没有标签的纽扣，想按形状或颜色分组。没有老师告诉你每个纽扣属于哪一类，你只能先选“相似”的定义，再探索分组结果。','无监督不等于没有目标。聚类有距离或概率目标，降维有保留变化和减少重建误差等目标。它们找到的是所选数学规则下的结构，不自动等于真实业务类别。','先在纸上画四五个点，并说清距离怎么算。每一步分配或压缩后，回到原数据检查“为什么它们被放在一起”。看懂结果比只知道函数名更重要。','向量|平均值|模型|特征|概率|迭代','clusters')
context('evaluation','两位同学都说自己做对了90%的题，但一个只做简单题，另一个专做难题，这个数字无法直接比较。模型评估也必须先约定数据、答案和计分规则。','不要把所有错误都压成一个数字。漏掉一个该找到的目标，和误报一个不该找到的目标，代价可能不同。先统计具体四类结果，再理解各个比例。','每个指标都先圈出分子与分母，用实际人数念出来。确定阈值、正类和样本范围后再算；最后挑几条错误样例，解释数字背后发生了什么。','标签|预测|阈值|比例|精确率|召回率|验证集|测试集','confusion')
context('neural','把做饮料看成一个计算过程：不同原料有不同用量，混合后再按规则处理，下一道工序继续使用结果。神经网络也由很多“加权组合→变换”小步骤连接而成。','“神经元”在这里是一个数学小单元，不是真的脑细胞。先算输入乘权重再求和，加上偏置，然后经过激活函数。多层重复这个过程，最终给出预测。','第一次读网络时只追踪一个样本、两个输入和一两个隐藏单元。先手算前向结果，再看损失，再看参数如何更新。不要把“得到预测”和“完成训练”当成同一件事。','神经网络|权重|偏置|激活函数|预测|损失|梯度|学习率','network')
context('torch','手工算一次梯度能帮助理解，但模型里可能有成千上万个参数。PyTorch相当于一个会记录计算步骤、自动组织数值计算的工具箱，让你不用逐个写出导数。','先分清数学原理与框架接口。Tensor保存数字，Module组织模型，优化器按规则更新参数。浏览器例子用于看懂原理；下面单独标出的本地代码才真的调用PyTorch。','顺序记成六个动作：准备数据→计算预测→算损失→清旧梯度→求新梯度→更新。清旧梯度也可放在前向之前，关键是每次更新使用正确的一次梯度。','矩阵|梯度|参数|损失|批次|训练|迭代','training')
context('vision','计算机读图片时，看到的不是“可爱的猫”，而是一大批像素数值。学习视觉，先把“图片里有什么”转成“数字怎样排列、希望输出什么”。','一张图可以有高、宽、颜色通道几根轴。分类给整张图一个类别，检测还要找位置，分割则给每个像素类别。它们需要不同的答案形式，不能只因为都看图片就混为一谈。','先画一个很小的数字格子，移动一个小窗口，逐格算一次。知道每个数字对应哪个像素，再理解卷积核、步幅和边界填充。','矩阵|特征|模型|标签|预测|维度','convolution')
context('nlp','人读一句话会利用词义和顺序，程序最初拿到的却只是文字。自然语言处理先决定怎样切分、编号和表示，再让模型从这些表示中寻找规律。','“把词变成数字”不等于机器已经理解了它。词频只记录出现次数，嵌入记录一组学习来的坐标，序列模型进一步利用顺序。每种表示都有保留和丢失的信息。','先用一句短句，手工分词、计数或编号，观察换词序后哪些表示会变化。这样才能判断一个特征到底能表达什么，不能表达什么。','字符串|列表|字典|token|嵌入|向量|特征','tokens')
context('transformer','你读“他把书放进书包，因为它太重了”时，会回看“它”指什么。注意力提供一种数字化的“比较上下文、挑出相关信息再汇总”的机制，但不等于人的理解过程。','先不看一整套大模型：先理解文字怎样变成编号，再理解一次查询怎样给两个候选分配权重。多个位置、多层和多头，是把小计算扩展到更大结构。','阅读公式时，先给每个字母贴上用途标签，再代入两项小数字。分词、前向计算、训练和生成是不同步骤，知道当前正在做哪一步，可以减少一半困惑。','token|嵌入|向量|点积|概率|注意力|权重|模型','attention')
context('generation','识别任务像“看见一幅画，说它是什么”，生成任务像“按某种规律再画一幅可能的画”。生成模型要学习的不只是一个固定答案，而是样本可能出现的分布。','压缩、重建、对抗和去噪是不同思路。理解它们时，先问输入究竟是什么、目标是什么、哪些步骤已知、哪些步骤要学习。不要把一个加噪演示误认为完整的图像生成模型。','从一个数字或二维点开始看过程。先理解信号变弱、噪声增加或表示压缩，再把相同思路扩展到图像。复杂图片的漂亮效果不能替代理解训练目标。','概率|模型|特征|损失|向量|训练','noise')
context('rl','玩迷宫时，某一步没有得分也可能让你更接近出口。强化学习关注连续决策：不是每一步都有标准答案，而是行动之后观察奖励和新状态，再学习长期更好的选择。','先区分状态、动作和奖励。状态是当前能观察到的情况，动作是可选择的行为，奖励是反馈数值。价值估计的是以后可能累计得到多少，不只是刚刚这一分。','先用三个动作或一条短轨迹手算回报。确认每一步的奖励位置和折扣次数，再看更新公式。奖励设计不合理时，算法可能很努力地做错事。','模型|概率|期望|参数|迭代|轨迹','rewards')
context('rag','开卷考试时，你可以先查资料，再组织回答。RAG也常先检索相关片段，再把片段交给生成模型。它不是把所有资料永久塞进模型记忆里。','把文档切块、建立索引、检索、重排、生成和引用拆成不同环节。某一步失败，后面再聪明也可能答错：如果没有找到正确证据，就不能凭空保证回答可靠。','先做不调用大模型的小检索器，亲自检查返回的每个片段和来源。之后再接生成，并要求回答中的重要结论能指向实际检索到的证据。','检索|候选|token|向量|排序|模型','retrieval')
context('agents','如果你让助手“帮我整理一份报告”，它可能需要先查资料、再核对、最后写作。Agent把多步骤的观察、选择和执行连起来，但每一步仍需明确权限和停止条件。','模型给出的“想做什么”不是执行许可。工具接口要检查名称、参数和权限。能用固定流程做好的工作，不必为了显得智能就变成无限自主循环。','先画一条三步流程，规定每步输入输出，再加失败分支。成功、失败、超时、预算耗尽都应该能够结束任务，避免同一操作重复执行。','函数|参数|字典|布尔值|模型|迭代','agent')
context('adaptation','买来一件外套后，可以只改袖口，也可以重新裁整件衣服；部署时还可换更轻的材料。模型微调、低秩适配和量化分别改变不同东西，不能把“更省资源”当作同一个技术。','先问你想改行为、学新任务还是降低运行成本。监督微调、偏好优化、LoRA、量化和蒸馏有不同目标；一种方法的优势不能直接推给另一种。','先数清哪些参数需要更新、哪些仍要保存，再看数据与效果。在纸上比较一个小矩阵和两个小因子的参数数量，低秩更新就不再只是缩写。','参数|矩阵|训练|权重|偏好|缓存','lowrank')
context('specialized','有些任务的关键不只在样本本身：推荐要考虑用户与物品，图学习要考虑连接关系，时间序列要考虑先后顺序。忽略这些结构，可能给模型一个根本不成立的题目。','先说明一条记录代表谁，以及它与其他记录有什么关系。预测未来不能看到未来的边或数值；未点击也不一定代表不喜欢，可能是用户根本没看到。','先用三个人、三个物品或五个时间点画出结构，再做一次最简单的统计。结构和评价方式清楚以后，才值得换更复杂的模型。','样本|特征|矩阵|向量|预测|平均值','graph')
context('classical-ai','走迷宫、排日程、检查规则，不一定需要训练神经网络。如果状态、动作和条件能够明确写出来，搜索或约束求解往往更容易解释和验证。','搜索是在可能的选择中寻找目标，规划还要考虑动作前提和后果。每一步看起来最靠近目标，不一定让最终路线最短，因为局部判断可能忽略后面的代价。','先画四五个状态与连线，再用队列逐项模拟。记录哪些状态已经访问、当前成本是多少、什么时候停止，比背算法缩写更重要。','列表|字典|循环|集合|候选|排序','search')
context('production','在自己电脑上成功预测一次，和让许多人稳定使用，是两件事。真实服务还要处理输入错误、等待时间、模型版本、日志、权限和恢复。','先把模型当成系统里的一个部件。数据先经过检查和预处理，再推理、后处理并返回。任何一步出错都要能定位，而不是只看到“AI失败了”。','从一个请求画出完整路径，并说明每一步谁负责、哪些信息可以保存。记录模型版本和数据版本；升级前验证，出问题能回到相互兼容的一套版本。','模型|预测|测试集|参数|缓存|比例','deployment')
context('research','一份学习记录最有用的不是“我看完了”，而是“我能用自己的话解释，能复现小例子，知道什么时候会错”。研究和独立项目都从这些可检查的小证据积累起来。','阅读和复现不是抄一份看起来能运行的代码。你需要知道问题定义、数据范围、评价标准和别人没有说明的假设。一次结果相同并不意味着所有条件都相同。','先复现最简单基线，每次只改一个因素，保存失败结果。最后请另一个不看你的解释的人按启动说明运行，看看它是否真的可重复。','模型|训练|验证集|测试集|平均值|比例','pipeline')
# Correct a glossary spelling alias used in adaptation.
GLOSSARY['偏好']=('比较两个结果时，认为哪个更符合目标。','偏好数据常给出同一问题的两个回答及较好的那个；它是相对比较，不是绝对正确性证明。')

NOTES={}
def note(i,analogy,explanation,worked,change):
    NOTES[i]=dict(analogy=analogy,explanation=explanation,worked=worked,change=change)
note(0,'把print想成一个显示窗口：你把要显示的东西交给它，它就在运行结果里写出来。它不会自动替你保存学习记录，也不会猜测你想说哪句话。','先看最外层：print是工具名，括号里是传给工具的内容。双引号把“今天开始学习 Python”围成一段文字；Python不会把这几个汉字当作变量名。括号与引号必须成对，使用键盘上的英文符号。','执行顺序是：①读到print；②取出引号中的文字；③把文字交给print；④显示文字并换行。输出里看不到引号，因为引号是代码中的边界，不是文字内容的一部分。','只把引号里的文字改成“我学会了第一行代码”。运行前先问：输出会保留引号吗？答案是不会。不要同时修改括号。')
note(1,'注释像菜谱旁边写的提醒，“这一步小心烫”。厨师会读懂提醒，但提醒本身不是另一道菜；Python会跳过#后面的说明。','代码里的5 * 20表示5乘以20，*才是Python乘号。print中逗号分隔多个要显示的内容，默认会在它们之间放一个空格。文字和算式可以交给同一次print。','先算5×20=100，再准备三段显示内容：“本周学习”、数字100、“分钟”。最后连成“本周学习 100 分钟”。第一行#注释不会出现在结果中。','把5改成7，20先保持不变。先手算7×20=140，再运行；之后在#后面写一句自己的提醒，确认输出没有变化。')
note(2,'变量像带名字的小标签。minutes不是“分钟”这个单位本身，而是你选的名字；你约定让它指向数字25，后面的代码才知道去哪儿取这个值。','minutes = 25先把右边的整数25准备好，再交给左边的名字。subject = "Python"保存的是文字。type(minutes)问的是“minutes目前指向什么类型”，.__name__取出类型的简短名称。','执行完第一行，minutes→25；执行完第二行，subject→"Python"。print依次取出两个值，所以显示Python 25。整数类型的名字是int，最后一行显示int。','把minutes改成25.5，猜最后的类型名是否仍为int。运行会看到float，因为小数是浮点数；变量的名字没有变，保存值的类型却变了。')
note(3,'input像问卷的输入框：无论你输入15还是你好，它首先收到的都是一段文字。计算前要明确告诉程序“请把这段文字当成整数读”。','int(input(...))有内外两层，必须从里面先算。input显示提示并拿到文字，再由int尝试转换。只有转换成功后，minutes才保存一个可以参加乘法的整数。','输入15：①input得到"15"；②int("15")得到整数15；③15赋给minutes；④minutes * 60得到900；⑤print显示900。一分钟有60秒，所以这是15分钟的秒数。','在输入框写3.5再运行。int不能直接把小数字符串读成整数，因此会报ValueError；如果任务允许小数，把int换成float，再比较输出。')
note(4,'把if分支想成依次经过的门：第一扇门条件成立，就走进去，后面的门不再尝试。并不是每扇门都独立执行。','>=读作“大于或等于”。minutes为20时，20>=30为False，于是检查elif；20>=15为True，选择第二段。else只在前面的条件都不成立时执行。缩进表示门里面有哪些动作。','从上到下判断：20够30分钟吗？不够。20够15分钟吗？够。因此输出“完成一道练习”。虽然20也大于0，但程序没有额外的分支需要你猜。','依次把minutes改成10、15、30，每次先写下将走哪个分支。特别观察恰好15和30的边界：>=包含等号那一刻。')
note(5,'循环像每天往储蓄罐放20元：不能每天先把罐子清空，否则永远只剩20。累计变量total需要在循环之前只初始化一次。','range(1,6)从1开始，到6之前停止，因此产生1、2、3、4、5。total += 20是total = total + 20的简写：取旧值，加20，再存回去。print退回最左边，表示五次循环全部结束后才显示。','小表：开始total=0；第1天20；第2天40；第3天60；第4天80；第5天100。循环的day只负责标识当前第几天，本例没有把day本身加进total。','把print缩进到循环里面，观察它会显示20、40、60、80、100。再退回最左边比较：同一行代码的位置改变，显示次数也改变。')
note(6,'把字符串看成一排有编号的字符抽屉。“study.py”中第一个s编号0，最后的y也可用-1表示。切片不是把文件真的剪坏，而是得到一段新文字。','strip()先去掉两边的空格；clean[:-3]省略开始位置，表示从最前面取到倒数第3个字符之前。因此去掉.py。split(".")按点号拆分，得到两个文字片段组成的列表。','原文字有两边空格；清理后是study.py，共8个字符。倒数3个是.、p、y；去掉后剩study。按点号拆分则得到["study","py"]，这次不是去掉后缀，而是保留两部分。','把name改成"  report.csv  "。先猜clean[:-3]是否还能正确去掉后缀：它会留下report.，因为.csv有4个字符。固定切几位不等于通用文件名解析。')
note(7,'列表像把几天的学习时间写在同一张表的一行里。append像在末尾加一个新格子，而不是重新打印整张表。','[15,20,25]是列表，逗号分开三项。minutes.append(30)直接修改原列表，追加后变成[15,20,25,30]。sum把四项相加；[-1]取最后一项。','原总和15+20+25=60。追加30后总和90，最后一项是30。所以输出先是90，再是30。append本身不返回更新后的列表，它的作用是修改原物。','试着先打印minutes，再append，再打印minutes。你会看到同一个变量中的列表变长。不要写minutes = minutes.append(30)，否则名字会被改为指向None。')
note(8,'字典像“学科→分钟数”的通讯录，集合像不重复的标签名单。两者都用花括号，但字典中有冒号连接键和值，集合则只放元素。','record.get("Python",0)表示找Python这个键，找不到就使用默认值0。集合中的两个"基础"是同一个标签，重复写也只保留一次。len数的是不同标签的数量。','字典里Python对应30，所以第一行输出30。标签写了三次，却只有“基础”和“练习”两种，因此长度是2。这里的2不是原来输入过几次，而是去重后有几项。','查询record.get("数学",0)，因为没有数学这个键，得到0。再换成record["数学"]，观察KeyError：两种读取方法对“找不到”的处理不同。')
note(9,'函数像一台专门的换算器：你给它分钟，它把分钟乘60再交回来。可以反复给不同输入，而不用复制整段代码。','def to_seconds(minutes)先定义规则，minutes是进入函数时的临时名字。return minutes * 60把计算结果交还。最后print(to_seconds(25))先调用换算器，拿到结果再显示。','调用时25交给函数里的minutes；25×60=1500；return交回1500；最外面的print显示1500。定义函数的那两行本身不会显示任何东西。','先把最后一行改成print(to_seconds(1))，得到60；再把return换成print，观察外层还会显示None。这样能亲眼区分“显示”和“返回”。')
note(10,'try/except像先尝试读懂一张纸条：如果内容不是整数，就走预先准备的备用流程，而不是让整个工具突然停止。','try里面执行可能失败的转换。except ValueError只处理“值的格式不对”这一类错误。assert检查条件是否为True，失败就主动提示测试没有通过，它不是输出结果的命令。','parse_minutes("12")先变成12，测试12==12通过，不显示内容。parse_minutes("abc")无法转整数，进入except并返回0，最后print显示0。','把测试改为assert parse_minutes("12") == 13，故意制造失败，看AssertionError。修回后再运行，理解测试是在检查行为，而不是替函数计算。')
note(11,'JSON像一张大家约定格式的记录卡。Python字典是程序运行中的对象；JSON文件是写在本子上的文字。保存和读取是两道不同工序。','with open(...,"w")打开准备写入的文件，w可能覆盖原文件。json.dump把字典写成JSON；ensure_ascii=False让中文按可读方式写入。再次open默认读取，再用json.load恢复成Python对象。','内存里先有subject与minutes两项；写入文件后内容成为JSON文字；读回后restored又成为字典；restored["minutes"]按键取出25。最后看到25，并不是文件名或整本记录。','把minutes改成40再运行，最后输出应为40。注意本网站中的record.json是浏览器临时文件，不会自动出现在电脑的下载文件夹。')

note(12,'计算器按固定公式工作，照片识别却要根据很多例子学习。两者都能帮忙，但并非任何程序都需要先训练。','本例不是让计算机自己判断任务，而是我们先写好三项需求与三项方法，再用zip把同位置的两项配成一对。算法选择仍需要人明确目标。','第一对是“固定税率计算”和“规则程序”；第二对是照片识别与分类；第三对是销量与回归。分类回答“属于哪类”，回归回答“具体多少”。','想一个自己的需求，先写清希望输出的是一个类别、一个数，还是一份满足规则的结果，再判断是否需要数据学习。')
note(13,'教孩子认字可以给“字→读音”的答案；也可以让他根据前几个字猜下一个字。后者从原材料本身就能构造练习。','[:-1]取除最后一项以外的前缀，[1:]取除第一项以外的后缀，zip按位置配对。两个列表错开一项，就形成“看到当前元素，预测下一个”的目标。','原序列[4,7,9,2]；输入部分[4,7,9]，目标部分[7,9,2]；配对后是(4,7)、(7,9)、(9,2)。样本数是3，不是4，因为最后一项没有下一个。','把序列换成[10,20,30]，自己先写出两对。真正语言模型的输入通常包含更长上下文，不是只看一个数字。')
note(14,'模型参数像已经调好的烤箱旋钮，超参数像决定“每次调多少、烤几轮”的实验计划。名字都带参数，但负责的事情不同。','model字典保存weight与bias，config保存learning_rate与epochs。预测只用前两者；本例读取了训练轮数，却没有执行训练循环。','weight=2.0，bias=1.0，输入3：先算2.0×3=6.0，再加1.0得到7.0。读取epochs得到5。代码输出两个数，不能据此说模型训练了5轮。','只修改epochs，预测应该不变；只修改weight，预测会变。这是区分模型规则与训练计划的一个小实验。')
note(15,'换了一种学习方法后分数从72涨到76，你先看到的是“多了4个百分点”，还不能直接说所有同学都会多4分。','两个分数需要来自同样的数据和评价规则。代码中的差值只描述这一次比较；不包含随机波动、不确定区间或因果判断。','0.76−0.72=0.04。如果写成百分数，76%−72%=4个百分点；相对于72%的比例提升约为5.56%，两种表述不能混用。','把新分数改成0.70，差值变负。给结果写一句完整解释，包含“在这份相同测试数据上”，避免夸大范围。')
note(16,'推导式像一条筛选流水线：先看一个数，要是符合条件，就对它加工并放进新盒子。','[x*x for x in values if x>0]要按“取数→检查→加工”的顺序读。最左边x*x写得靠前，但只有右边条件通过后才把结果放进去。','-2不大于0，跳过；0也不大于0，跳过；3通过，平方为9；5通过，平方为25。最终新列表只有[9,25]，原values仍保留四个数。','把>0改成>=0，结果会多一个0。这个小改动说明筛选边界也属于算法规则。')
note(17,'一个模型对象像一台带有自己刻度的换算器。两台换算器可以存不同的权重，而使用同名的predict方法。','__init__在创建对象时设置状态。self.weight表示“这一台对象保存的权重”。调用model.predict(4)时，self自动指向model，你不需要把self再手动传一次。','创建LinearModel(3,2)后，对象保存weight=3、bias=2。predict收到x=4，计算3×4+2=14并return。最后print显示14。','再创建另一个LinearModel(1,0)，比较两个对象对4的预测。两台对象不会因为方法名字相同就共享同一组参数。')
note(18,'把五本书分批搬，每趟最多拿两本，需要三趟，最后一趟只有一本。yield让你每次只交出一批，而不是一次塞进所有结果。','range(0,len(data),size)从0开始，每次跨size步。切片[start:start+size]取一批，到列表末尾时自动变短。yield交出当前批并暂停，下一次继续。','start依次是0、2、4；对应切片[0:2]→[1,2]，[2:4]→[3,4]，[4:6]→[5]。list(...)在这里把三次交出的批次收集起来显示。','把批大小改成3，先猜会分成[1,2,3]与[4,5]。size=0不合法，因为循环无法前进。')
note(19,'两个购物清单逐项相乘时，如果一个三项、另一个两项，少掉的那项不能悄悄忽略。形状检查相当于先核对清单长度。','a:list只是提醒读代码的人a应该是列表，不会自动检查每项。len检查长度，raise主动报错；zip长度不同时会按较短的一边结束，所以先校验非常重要。','[1,2]与[3,4]先配成(1,3)、(2,4)，分别相乘3与8，再相加11。这里的点积与前面线性代数中的同名计算一致。','把b改成[3]，观察明确的长度错误。再试着删去校验，看看不完整的计算如何“看起来还能运行”，却算了错误的问题。')

note(20,'把[3,4]想成从原点出发：向右走3格，再向上走4格。L1算按街区走了几格，L2算两端之间的直线距离。这个类比只用于坐标，不代表所有特征都有物理方向。','L1中的绝对值去掉方向：|-3|也算3。L2先分别平方，避免正负抵消，再求和，最后开平方。平方根用于把“平方单位”变回原单位。','L1：|3|+|4|=7。L2：3²=9，4²=16，9+16=25，√25=5。为什么不是√3+√4？因为公式规定先把平方加起来，再整体开根。','把向量换成[-3,4]。它朝左上方，但L1仍7、L2仍5；长度变不变与方向变不变是两回事。')
note(21,'两个人推同一辆车，方向越一致，彼此的贡献越容易相加。余弦相似度关心方向是否一致，而不是只看谁用的力量更大。','点积先按位置配对，再求和。范数是各自长度。余弦把点积除以两者长度，去掉整体倍数的影响。余弦可能为负，表示方向相反；零向量没有可用方向。','a=[1,0]，b=[1,1]。点积1×1+0×1=1。a长度√1=1，b长度√2约1.4142，因此余弦1÷1.4142≈0.7071。它不是70.71%的事实可信度。','把b改成[2,2]：点积变2，b长度也变为原来2倍，除法后余弦不变。再试b=[-1,0]，余弦应为-1。')
note(22,'一行像一份“配料方案”，一列像某种输出所需的配比。矩阵乘法让每份方案与每列配比组合，生成一张新的结果表。','结果的一个格子来自左矩阵的一整行与右矩阵的一整列。左边2行、右边2列，结果有2×2个格子。行里有2项、列里也有2项，所以能成对相乘。','左上：1×2+2×1=4。右上：1×0+2×2=4。左下：3×2+4×1=10。右下：3×0+4×2=8。按行排列结果是[[4,4],[10,8]]。','先只手算一个格子，再运行核对。把两个矩阵交换位置，通常结果会变；矩阵乘法不像普通数字乘法那样普遍可交换。')
note(23,'你发现买1杯饮料加包装共3元，2杯共5元，3杯共7元。多一杯多2元，固定包装费1元，于是能写出总价=2×杯数+1。','最小二乘在数据不完全排成直线时，寻找总体平方误差较小的直线。这里先用整齐数据让计算透明：斜率w表示x每增加1，y增加多少；截距b表示x=0时预测多少。','x均值2，y均值5。分子(-1)(-2)+0×0+1×2=4；分母(-1)²+0²+1²=2；w=4÷2=2。b=5−2×2=1。逐点代回会全部吻合。','把最后的7改成8，点不再严格共线。观察拟合直线如何折中，而不是要求每个点都完全对上。')
note(24,'有些方向经过一台“拉伸机器”以后仍沿原来的直线，只是变长、缩短或反向。这样的方向可以帮助我们理解变换的主要作用。','特征向量必须非零。Av=λv的意思是“先做矩阵变换”与“把原向量乘同一个数”得到同样结果。λ读作lambda，它是本题的缩放倍数。','A=[[3,0],[0,1]]，v=[1,0]。Av第一项3×1+0×0=3，第二项0×1+1×0=0；另一方面3v=[3,0]。两条路线完全一致，所以v对应λ=3。','把v换成[0,1]，它对应的倍数是1；换成[1,1]后两个分量分别变3与1，不能再用同一个倍数描述。')
note(25,'一家餐厅有很多菜，但顾客喜好可能大致由“爱辣”和“爱甜”这两个隐藏因素概括。每个人与每道菜都给两个系数，就能估计很多组合，而不必逐对记忆。','低秩表示用较少独立方向组合出大表格。浏览器例子只展示“因子相乘形成评分”，没有求SVD。潜在因素在实际训练中不一定恰好是辣或甜，只是帮助入门的类比。','用户[1,2]对菜[2,0]得1×2+2×0=2；对[0,3]得6；对[1,1]得3。第二个用户[2,1]得到4、3、3，因此完整结果是[[2,6,3],[4,3,3]]。','自己增加第三个物品因子，先算两个用户对应的分数。原表多一列，但每个物品只需要存两个因子。')

note(26,'汽车在某一秒的速度，不能靠“出发以来平均每小时多快”完整描述。导数关心当前位置附近的变化速度。','先比较两个很近的位置：x+h与x−h。两处输出的差是分子，输入跨度是2h。用输出差除以输入差，就是这小段的平均变化率；h足够小时可近似局部变化率。','x=3，h=0.0001。右边3.0001的平方为9.00060001，左边2.9999的平方为8.99940001。差0.0012，输入差0.0002，商为6。恰好接近解析导数2x=6。','把x改成1再算，导数应接近2。相同函数在不同位置斜率不同，因此不能把“x²的导数是6”当作对所有x成立。')
note(27,'一座山可以同时往东西和南北两个方向走。你固定南北位置，只问向东走一点地面多高；再固定东西位置，问向北走一点。这是分别观察变化。','f=x²+3y²有两个独立输入。对x求偏导时，3y²暂时当不随x改变的常数；对y求偏导时，x²当常数。梯度把两个变化率按[x方向,y方向]排在一起。','x=2、y=-1。对x的变化率2x=4；对y的变化率6y=-6，所以梯度[4,-6]。负号不是“算错了”，而是说明增大y会在此处降低函数值。','把y从-1改成1，第二项梯度从-6变6。这说明当前位置会改变往哪个方向走才能下降。')
note(28,'你先把旋钮w变成预测，再把预测变成误差，最后把误差平方。要知道旋钮动一点会怎样影响最终损失，就沿这条链逐段相乘。','令e=wx−t，L=e²。w改变先影响e，变化率是x；e再影响L，变化率是2e。两段连在一起，所以dL/dw=2e×x。这个式子不是需要背诵的魔法，而是两段变化的组合。','w=2、x=3、t=5。预测6，误差1，损失1；误差对w的变化率3，损失对误差的变化率2，所以对w的梯度6。微小增加w会使此处损失上升。','把目标t改成7，误差变-1，梯度变-6。这次应该增大w才能靠近目标，负梯度更新会给出这个方向。')
note(29,'你想摸到碗底，但每次只知道脚下往哪个方向更低。梯度下降就是先测当前坡度，再按坡度的反方向走一小步。','本例“碗”是L=(w−3)²，最低点在w=3。梯度2(w−3)描述当前斜率。w←w−学习率×梯度中的减号非常重要，它让你往损失减少的方向走。','开始w=0：梯度-6，步长0.1×(-6)=-0.6，更新0−(-0.6)=0.6。第二次梯度2(0.6−3)=-4.8，新w=1.08。后面是1.464、1.7712、2.01696。','把lr改成1.1，仅看前几次w如何在3两侧越跳越远。方向正确也可能因为步子太大而失败。')
note(30,'看一个人走路，一次迈左不代表他在向左走；可以综合最近几步判断整体方向。动量也把历史梯度和当前梯度混合。','本例采用v←0.9v+0.1g。新v保留90%的旧累积，再加入10%的当前梯度。它是指数平滑的一个约定，并不是所有框架动量公式的唯一写法。','v从0开始。g=2时v=0.2；g=-2时v=0.9×0.2−0.2=-0.02；g再次为2时v=0.9×(-0.02)+0.2=0.182。交替信号被平滑了。','把beta改成0，v每次完全等于当前梯度，不再保留历史。再改成0.99，观察短期变化更缓慢。')
note(31,'把弯曲边界下的面积切成很多窄长条，每条用一个小矩形近似。条越细，通常越接近真实面积，但计算和数值误差也需要考虑。','积分可以表示连续累计。本例每条宽度1/n，中点(i+0.5)/n处高度是x²。面积近似等于所有高度相加再乘宽度。这里取中点，没有随机抽样，所以不是蒙特卡洛算法。','先只用n=2理解：中点0.25、0.75，高度0.0625、0.5625；各乘宽0.5，总面积0.3125。用1000条得到约0.3333，接近精确值1/3。','先运行n=2，再改为10、1000。不要只是看小数更长，要比较它离1/3是否更近。')

note(32,'有1000个抽象样本，其中100个真正具有事件A。检测并不完美：能找出其中80个，却也把其他900个中的180个误报。','问“检测阳性之后，A的概率是多少”，分母是所有阳性，不是全部人。阳性总数80+180=260，其中真正A有80，因此要算80/260。','先验0.1相当于100/1000；命中率0.8相当于80/100；误报率0.2相当于180/900。后验80/260≈0.3077。80%不是最后问题的答案，因为它回答的是反方向条件。','把先验改成0.01，其他值不变，先按10000个样本列出人数再运行。你会看到基础比例改变会显著改变阳性后的判断。')
note(33,'两天都平均学习20分钟，可能是每天20、20，也可能是0、40。平均值相同，不代表波动也相同。','方差先求平均，再计算每个值离平均有多远，平方后取平均。平方让正负偏差都变成非负贡献，避免互相抵消。本例把列表当作等概率总体，分母用n。','[1,2,3]均值2；偏差[-1,0,1]；平方[1,0,1]；总和2；除以3得到2/3≈0.6667。平方根约0.8165是标准差，不是方差本身。','把列表改成[2,2,2]，均值仍2，方差变0，表示每项都没有偏离平均值。')
note(34,'抛4次公平硬币，恰好2次正面，不只有“前两次正面”这一种顺序。必须数出所有满足条件的排列。','C(4,2)表示从4个位置中挑2个放成功，共6种选择。每种指定顺序的概率都是0.5⁴=1/16，因为假设每次独立。6种互不重叠结果相加。','可把成功位置列成(1,2)、(1,3)、(1,4)、(2,3)、(2,4)、(3,4)。因此概率6×1/16=0.375。math.comb帮助数位置组合，后面两项计算每种顺序的概率。','把k改成0，只有全部失败一种顺序，概率1/16。不要把“成功次数0到4共有5种”误认为每种次数都一样可能。')
note(35,'看一枚未知硬币抛了5次，出现3次正面。你想找一个成功概率，让这组结果在模型里尽量说得通。','对伯努利观测，最大似然估计是成功次数除以总次数。本例只做这个已知结论的计算，不通过搜索所有候选概率求最大值。似然比较的是“若参数如此，数据有多可能”。','outcomes里1记成功、0记失败。sum得到3，len得到5，3/5=0.6。这里0.6是由这5次记录估计出来，不是硬币真实概率已被证明等于0.6。','再添加5次结果，比较估计如何变化。只有一次成功时最大似然会得到1，但显然不能据此断言以后永远成功。')
note(36,'从一个盒子里有放回地取3个数，可能取到相同值多次。每次形成的小样本平均不同，能帮助观察统计量的波动。','Bootstrap是用已有样本有放回重抽样。本例不真正随机抽很多次，而是给出3份预设重采样，让你能手算每一个均值；因此不能据此声称得到可靠置信区间。','[1,1,3]平均5/3≈1.667；[1,2,3]平均2；[3,3,2]平均8/3≈2.667。round保留到3位，显示列表中的2.0而非强制显示2.000。','自己再写一份[1,3,1]，它的顺序不同但均值同第一份。重采样主要关注抽到了什么，不是仅把顺序打乱。')
note(37,'冰淇淋销量与游泳人数可能一起增加，因为天气热同时影响它们；不能直接说多卖冰淇淋导致更多人游泳。','相关系数比较两个变量偏离各自均值的方向是否一致，再除以各自波动的尺度。它衡量线性共同变化，不回答改变一个变量会造成什么后果。','x均值2，y均值4；偏差分别[-1,0,1]和[-2,0,2]。配对乘积相加4，分母√(2×8)=4，得到相关系数1.0。两组数完全同向线性变化。','把y换成[6,4,2]，相关变-1。再试一个弯曲关系，看看强烈的非线性联系不一定体现为很大的线性相关。')
note(38,'你对两个盒子的内容作预测：一个你给正确颜色80%概率，另一个只给20%。如果最后都出现那个颜色，前者应该受到更小惩罚。','信息论常用负对数把“给真实结果的概率”变成损失。概率越接近1，-log越接近0；概率很小时，损失很大。熵还需要对所有结果按真实概率加权。','公平二元分布：-0.5log₂0.5−0.5log₂0.5=1比特。正确类概率0.8时，负自然对数约0.2231；这两个数采用的对数底不同，含义也不同。','把最后的0.8改成0.2，损失变大。先判断方向再算，能帮助你发现漏写负号之类的错误。')
note(39,'投票得分可能是1000与1001，但我们想比较它们，而不是让计算机直接计算极大的指数。给所有人同时减去1001，不会改变谁更领先。','Softmax先把分数变成正数，再除以总和。减去最大分数后，两项是-1与0，对应指数约0.3679与1，总和1.3679。每项再除以总和便得到概率。','第一项约0.3679/1.3679=0.2689，第二项1/1.3679=0.7311，和约1。数值很大的原分数并不意味着第二项概率接近100%。差值才起关键作用。','把输入换成[0,1]，答案应相同。再换成[0,10]，第二项才会很接近1。')
note(40,'用只有固定刻度的尺子量长度，很多真实长度只能近似记录。计算机浮点数也只有有限二进制位置，不能精确表示所有十进制小数。','0.1和0.2在内部通常存成非常接近它们的二进制数；加完可能稍微偏离0.3。==问逐值是否恰好相等，isclose问差异是否落在约定容差内。','0.1+0.2常显示为0.30000000000000004。因此严格比较得到False，容差比较得到True。这不是加法规则失效，而是有限表示造成的微小误差。','试试round(0.1+0.2,1)再比较。它可用于某些显示任务，但科学计算中的容差应按量纲与误差要求选择，不宜随便四舍五入一切。')
note(41,'一张表每行是一位同学的三项成绩，现在给所有同学的三科分别加10、20、30分。每一行都使用同一份加分表。','广播的核心是沿某些维度重复使用同一组数。浏览器代码用两层循环明确写出这个动作，并不是Python列表自动支持广播。矩阵2×3与偏置长度3的列位置正好对应。','第一行[1,2,3]分别加[10,20,30]得到[11,22,33]；第二行[4,5,6]得到[14,25,36]。行数没有变，列数也没有变。','把bias缩短成两项，看zip会悄悄截断最后一列。真正工程中应先检查形状，不要把“程序没报错”当作计算完整。')
note(42,'按班级计算平均分时，缺考不一定代表考了0分。先决定缺失值的意思，才知道该怎样统计。','None表示这里没有数值。代码先跳过None，再按A或B分组，最后对每组有效数值求平均。setdefault在第一次见到新组时准备一个空列表。','A组保存[2,4]，平均(2+4)/2=3；B组跳过None，仅剩[8]，平均8/1=8。若把None补成0，B平均会变4，这已经是另一个统计问题。','把B组所有值都改成None，它不会出现在当前结果里。思考实际报表应该显示“无有效数据”还是省略，别让业务含义由代码偶然决定。')
note(43,'老师把学生成绩按分数数一遍，可以先看到哪些分数最多，再决定是否需要更复杂的图。画图之前，频数表已经提供重要信息。','Counter数每个值出现几次；sorted按值排序，便于阅读。计数不是概率，要得到比例还需除以总样本数。远离其他值不自动意味着数据录错。','[1,1,2,2,2,5]共6项。1出现2次，2出现3次，5出现1次，字典为{1:2,2:3,5:1}。值2的比例3/6=50%。','把一个2改成5，先在纸上更新频数，再运行。若后面绘制直方图，需要说明分箱方式，不能把整数频数图与任意分箱混为一谈。')
note(44,'CSV像把表格用逗号分开写在文本里。计算机读到“20”时还不知道你要把它当作分钟数，还是一个编号。','DictReader把第一行作为列名，每一行变成字典。row["minutes"]取到的是文字，因此int负责转换。StringIO只是把内存里的文字包装成能按文件方式读取的对象。','两行minutes分别是"20"和"30"；转换后20与30相加得到50。若直接拼接文字，会得到"2030"，完全不是总分钟数。','把某一行分钟写成abc，观察转换报错。真实数据清洗需要决定记录错误、跳过还是中止，而不是静默把所有异常都变0。')
note(45,'预测未来销量时，考试题必须来自未来，不能把未来记录混进训练。划分顺序要模拟真正使用的时间顺序。','列表切片不包含结束位置：[:6]取索引0到5，[6:8]取6和7，[8:]取8以后。这里的比例是6/2/2，并不是所有项目都必须采用的唯一比例。','原数据1到10：训练[1,2,3,4,5,6]；验证[7,8]；测试[9,10]。每个记录只属于一份，而且过去与未来没有交叉。','如果同一用户有很多记录，单按行随机切分可能让相同用户跨集合。写下你自己项目的一条样本和划分单位，再决定怎么切。')
note(46,'把温度和工资放到同一距离公式里，工资数值更大，可能几乎决定了距离。标准化帮助把不同尺度放到较可比的范围，但不能替代理解含义。','先减训练均值，让中心移到0；再除以训练标准差，按波动大小缩放。这个变换不是把所有数都塞到0到1，标准化后可以有负值。','[1,2,3]均值2，方差2/3，标准差约0.8165。三个偏差-1、0、1分别除以0.8165，约为[-1.225,0,1.225]。','测试值4也要减原均值2、除原标准差，而不是单独给测试集重新算一组参数。这样训练与预测才在同一把尺子上。')
note(47,'用三盏灯表示颜色：红灯、绿灯、蓝灯。绿色只点亮第二盏。这样不会暗示“蓝比红大3倍”。','one-hot让每个类别占一列，当前类别对应1，其他列0。代码逐个比较color与词表项，比较结果先是布尔值，int再将True/False变成1/0。','词表[红,绿,蓝]固定。绿色对红判断False→0，对绿True→1，对蓝False→0，所以得到[0,1,0]。位置顺序就是含义的一部分。','把color改成黄，当前结果全0。真实接口要明确未知类别规则，不应把黄偷偷归到红。')
note(48,'班上95人没迟到、5人迟到。一个系统永远说“没迟到”，也能答对95人，但对寻找迟到者毫无帮助。','准确率的分母是所有样本。正类比例的分母也是所有样本，但分子不同。两个数要放在一起看，才知道多数类基线是否掩盖了目标类。','100个标签中0有95个，因此永远预测0的准确率95/100=0.95。真正正类只有5/100=0.05；该系统找对的正类数为0，召回率也为0。','把正类数量增加到50，准确率基线会变0.5。数据分布一变，同一个“全部猜0”策略的漂亮分数就消失了。')
note(49,'每杯饮料2元加1元包装，用ŷ=2x+1预测总价。真实数据可能有优惠或测量误差，因此预测不一定每次对上。','帽子符号ŷ读作“y的预测值”，不带帽子的y是真实目标。MSE先对每一对预测与目标作差、平方，再除以样本数。必须先逐项对齐。','x=[1,2,3]预测[3,5,7]，目标[3,5,8]。误差[0,0,-1]，平方[0,0,1]，平均1/3≈0.3333。它不是平均误差-1/3。','把最后目标8改成10，误差平方变9，MSE变3。误差变3倍，平方惩罚会变9倍。')
note(50,'温度计上的连续读数与“是否发烧”的决定是两步。逻辑回归也先给一个概率，再通过阈值变成类别。','sigmoid把任意实数得分变成0到1之间的数。得分0对应0.5，正数对应更大概率，负数对应更小概率。阈值0.5只是本例的约定，不是自然定律。','得分-2得到约0.1192，0得到0.5，2得到约0.8808。按≥0.5规则，三个类别为[0,1,1]，中间的等号决定0.5归哪一边。','把阈值改为0.8，概率本身不会改变，只有决策改变。把概率列表和类别列表分开打印以免混淆。')
note(51,'来到新小区，你想根据离你最近的邻居习惯作判断。kNN就用“附近样本的答案”来形成新样本的预测。','先定义距离，本例是一维绝对差。排序后取前2个，距离并列时保留原样本顺序。第二次输出把邻居标签求平均，是一个简单的软投票数值。','查询3：点1距离2，点2距离1，点5距离2。排序先点2，再点1（并列保持原顺序），两者标签都是0，平均0.0。','把查询改成4，点5最近；第二近点2距离2，比点1更近。看看近邻列表和投票如何一起变化。')
note(52,'一袋球如果全是同色，很容易猜下一次颜色；红蓝各一半则更难。基尼不纯度把“这一组混杂多少”量化。','先算每类比例，再分别平方，最后用1减去平方和。它不是每个样本的错误次数。树会比较切分前后加权不纯度，选择更能分开的划分。','红蓝各一半时：1−0.5²−0.5²=1−0.25−0.25=0.5。全红时：1−1²=0。0代表组内已经纯，不是“分类器准确率为0”。','把标签改成三个0、一个1，手算1−0.75²−0.25²=0.375。比例更不均衡，组内更接近单一类别，不纯度降低。')
note(53,'三位估价员分别估2、4、3元，取平均可以缓和某个人偏高或偏低的影响。但如果三人都看错同一份资料，平均也未必正确。','本例只是已有预测的平均，不包含训练树。随机森林通过不同数据和特征选择产生多棵树，提升方法则逐步修正前面的不足，它们不是同一种训练流程。','2+4+3=9，除以3得到3.0。要先得到每个模型对同一个样本的预测，才能沿模型这一维求平均。','把三个预测都设成10，平均仍10。集成的作用不是自动消除所有偏差，需要模型误差具有适当差异。')
note(54,'跳远不仅要跨过线，还希望留出安全距离。SVM里的间隔也不只问“方向对不对”，还问离分界是否足够远。','标签这里用+1或-1。y×score叫带标签的间隔；达到1或更大时hinge损失为0，不足1时按差额惩罚。max(0,...)保证不会出现负损失。','标签+1、得分0.4：间隔0.4，损失max(0,1−0.4)=0.6。虽然得分已经是正数、分类方向正确，但还没达到要求的间隔1。','把score改成2，损失0；改成-0.4，损失1.4。错误方向通常会受到更大惩罚。')
note(55,'你看到一封信同时提到促销和中奖，想比较“垃圾邮件”和“正常邮件”哪个解释更符合这些线索。先验和线索概率需要一起看。','两个类别先各算一个未归一化分数，再除以两类分数总和。这里只在简化条件独立假设下相乘；真实文本里的词往往相关。','垃圾类分数0.4×0.8×0.5=0.16；正常类0.6×0.1×0.2=0.012。垃圾类归一化0.16/(0.172)≈0.9302。0.16本身不是最终后验。','只改变先验0.4和0.6，会改变最终结果。试着解释“先前常见程度”和“当前线索”分别在公式的哪一部分。')
note(56,'一条绕着每个点拐弯的曲线可能把练习全部背下来。正则化像给复杂解加一道成本，让模型不能只顾训练误差。','L2平方惩罚把每个权重平方后加起来，再乘强度λ。λ是人为选择的控制值；它不是模型直接从这段代码学出来的参数。','权重[3,4]的平方和9+16=25；强度0.1，惩罚2.5；原数据损失2.0，总目标4.5。目标变大不一定代表模型更差，因为现在衡量标准多了一项约束。','把权重改成[0,0]，惩罚为0，但不能据此说预测最好，还要看数据损失。两部分必须一起权衡。')
note(57,'给一排住户安排两个服务站：住户先选近站，服务站再搬到自己服务人群的平均位置，然后重复。k-means的两步就像这样。','本例只执行一轮：根据旧中心分配点，再算新中心。不能先更新一个中心就立刻用它去改变同一轮其他点的分配，否则混用了新旧状态。','初始中心1与9。点1、2更近1，点8、9更近9。第一组均值(1+2)/2=1.5，第二组(8+9)/2=8.5。','从不同初始中心开始，比较一轮后的分组。遇到空簇时无法求均值，需要额外规则，而不是让程序除以0。')
note(58,'把一张立体景物压成影子，会保留一些方向的信息，也会丢掉其他方向的变化。降维同样需要说明压掉了什么。','示例手工把二维点投影到x轴：保留x、把y变0。它没有求最佳主方向，只用于理解重建与误差。每个点的两项平方差相加后，再对点数取平均。','点[1,0.1]重建[1,0]，误差平方0.01；[2,-0.1]同样0.01；[3,0]误差0。总和0.02除以3，约0.0067。','把第二坐标都放大10倍，误差平方会放大100倍。特征单位会直接影响“保留变化”的含义。')
note(59,'一个人的身高比班级平均高很多，可能值得检查，但不代表一定量错。异常检测给出的是“离常规多远”的线索。','z-score把偏离均值的距离换成“几个标准差”。本例看绝对值，因此过高和过低都会被标记。>3不包含恰好3。','均值10、标准差2：值10的z=0；12的z=1；18的z=4。绝对值是否大于3分别False、False、True。','把18改成16，z恰好3，按>3规则不会标记。边界如何定义必须提前说明。')
note(60,'看到一个模糊物体，你可能觉得60%像第一类、40%像第二类，而不是立刻硬选。软分配保留这种不确定性。','每个成分先用“在总体中多常见”乘“它对当前样本的解释程度”，再把两项归一化。两项责任度加起来是1，表示当前模型对归属的相对分配。','第一项0.3×0.8=0.24，第二项0.7×0.2=0.14，总和0.38。责任度约[0.6316,0.3684]。单看0.8大于0.2，会漏掉先验权重。','把两个似然设成一样，归一化后责任度就等于原先的混合权重。可以由此检查分母是否写对。')
note(61,'抓垃圾邮件时，“抓到的有多少是真的”和“所有垃圾里抓到了多少”是两个不同问题。先说清分母，公式就不容易背反。','TP是真正抓对，FP是误抓，FN是漏掉。精确率TP/(TP+FP)只看被抓那一群；召回率TP/(TP+FN)只看真实垃圾那一群。','TP6、FP2，所以精确率6/8=0.75；TP6、FN4，所以召回率6/10=0.6。F1=2×0.75×0.6/(0.75+0.6)≈0.667。','画出8个被抓样本与10个真实正类，标出它们共享的6个。不要把8和10当成互不重叠的两组人。')
note(62,'如果每次拿一个正样本和一个负样本比赛，正样本得分更高就记一分，AUC可以用这个配对比赛来理解。','本例两正两负共有2×2=4场。并列按半分处理。它只比较顺序，不要求先选一个分类阈值，因此不等于准确率。','0.9分别赢过0.7、0.2，两分；0.6输给0.7、赢0.2，一分。总3分除以4场，AUC=0.75。','给所有分数同时加100，排名不变，AUC也不变。校准概率却不能随便加100，这说明排序和概率是不同对象。')
note(63,'一次模拟考碰巧遇到熟悉题，不代表所有考试都这么容易。交叉验证换几批题目作为验证，观察结果是否稳定。','三个分数来自三个不同验证折的完整训练流程。本例仅汇总已有结果，没有真的训练三个模型。极差是最大减最小，只描述这几个数的跨度。','(0.7+0.8+0.9)/3=0.8；0.9−0.7=0.2。0.8不是保证未来准确率80%，0.2也不是置信区间。','把一个分数改成0.2，均值下降、极差增大。先追查是哪一折的数据或分布特殊，而不是只留下最好一折。')
note(64,'一个天气预报系统长期说80%下雨时，如果十次里大约八次真的下雨，它的概率就比较有解释性。猜中最多和概率说得准不是同一件事。','Brier分数逐项比较概率与0/1真实标签，用平方误差求平均。预测0.8、实际1的偏差是-0.2；预测0.3、实际0偏差0.3。','平方分别0.04与0.09，平均(0.04+0.09)/2=0.065。分数越小通常越好，但比较时仍需同一数据和目标。','把第一个概率改成0.99，若真实仍1，该项误差更小；若真实变0，误差会变很大。自信需要与实际结果一起评价。')
note(65,'先把两种输入按配方混合，再把负数截成0。这就是本题两个隐藏单元在做的事，不需要想象神秘的大脑过程。','每一行权重对应一个隐藏单元。第一单元取输入[2,-1]与权重[1,1]做点积；第二单元用[-1,1]。ReLU就是max(0,计算值)。','第一单元2×1+(-1)×1=1，ReLU后1。第二单元2×(-1)+(-1)×1=-3，ReLU后0。隐藏表示[1,0]，求和输出1。','把输入第二项从-1改成3，两个隐藏单元都可能激活。先逐个算，再看最终输出，别直接跳到最后的sum。')
note(66,'sigmoid像一根两头逐渐变平的曲线。中间位置输入动一点，输出比较明显地变；靠近两端时，输入再动，输出变化很小。','导数s(1−s)反映曲线当前坡度。在z=0时s=0.5，乘积0.25；在z=5时s接近1，另一项1−s很小，所以坡度也小。','z=5时s约0.9933，1−s约0.0067，乘积约0.0066。多层连乘这些小数，会让早期层接收到的变化信号很弱。','计算z=-5，导数与5附近相近。输出接近0与接近1都可能是饱和区域，不只是正数那边。')
note(67,'你想找出一个倍数，让1变2、2变4、3变6。我们知道答案是2，但这次让程序从0开始，用错误反馈一步步靠近它。','每轮先用当前w预测，再算MSE对w的梯度。对每个样本是2(wx−y)x，三个样本求平均；最后w减去0.05倍梯度。没有把答案2直接赋给w。','第一次w=0，误差[-2,-4,-6]；误差乘输入[-2,-8,-18]，和-28；乘2再除3得-18.6667。更新w≈0.9333。第二轮重新预测，误差会缩小。','把循环轮数从100改为1，输出接近0.9333；再改为5、20、100，观察逐渐靠近2。这个过程才是在训练。')
note(68,'把10本书每趟搬4本，需要3趟；这样完整搬一次叫一轮。搬三轮总共9趟，不是3趟。','N是样本数，B是批大小。ceil表示向上取整，因为最后2个样本也需要一次更新。这里假设每一批更新一次，且不丢最后一批。','10÷4=2.5，向上取整得到3批；每轮3次更新，3轮总9次。最后一批小，并不代表可以忽略。','把batch_size改成5，每轮2批，三轮6次。轮数没变，但参数更新次数变了。')
note(69,'原来的计划是[1,2,3]，一个小助手只建议改动[+0.1,-0.2,0]，而不是重写整个计划。残差连接就是把修正加回原输入。','F(x)可以是复杂网络，但这里只给定一组修正。残差相加是逐元素相加，不是列表拼接。输入与修正需要相同形状，或者先做合适投影。','第一项1+0.1=1.1，第二项2−0.2=1.8，第三项3+0=3.0。输出保留原始信息并加入改动。','把所有修正改成0，输出应与原输入相同。这条“可以什么也不改”的通路是理解残差的好起点。')
note(70,'复习越久，可能只是把练习册背得越来越熟。你需要看没参与训练的模拟题何时表现最好，而不是只看练习错误越来越少。','validation列表按轮次保存损失，越小越好。min(range(...),key=...)比较的是每个位置对应的值，并返回位置编号；Python位置从0开始，显示第几轮要加1。','五轮损失0.8、0.6、0.5、0.55、0.7，最小0.5在索引2，所以最佳轮次2+1=3。后面更差，不应自动选择最后一轮。','把第五轮改成0.4，最佳位置就会变到第5轮。早停策略还常加等待窗口，不只是遇到一次变差立刻停。')
note(71,'手工知道x²的导数是2x以后，可以让框架记录同样的计算，检查它是否给出一致梯度。先有可手算的答案，再使用自动工具更可靠。','浏览器中的两行是解析计算，不会真的调用PyTorch。可下载的本地代码才创建Tensor、开启requires_grad、计算y，再调用backward把梯度写入x.grad。','x=3.0，前向y=3×3=9.0；导数2×3=6.0。注意9是函数值，6是当前位置变化率，两者单位和用途不同。','把x改为4，函数值16、梯度8。不要期待梯度与输出总是一样。')
note(72,'用手工方法学会一轮更新后，再把相同流程交给训练框架。框架减少重复工作，但不会替你决定标签是否正确。','本地示例Linear(1,1,bias=False)只有一个权重。optimizer持有要更新的参数。zero_grad清理上一轮梯度；loss.backward计算新梯度；step实际修改权重。','浏览器简例最小化(w−2)²：w从0开始，第一步梯度-4，以0.1更新得到0.4；第二步得到0.72。50步以后舍入接近2.0。','暂时去掉本地代码里的optimizer.step，思考参数会不会改变。得到梯度不等于已经应用更新。')
note(73,'知道书本身多重，还不能推断搬家需要多大车；还要加包装箱、工具和其他物品。模型权重大小也不是完整训练内存。','字节是存储容量单位。每个参数用4字节，100万个就是400万字节；用2字节减为200万。训练还要梯度、优化器状态、激活和临时缓冲。','1,000,000×4=4,000,000字节；×2=2,000,000字节。十进制MB与二进制MiB换算不同，所以这里先直接输出字节，避免混淆。','把参数数增加10倍，权重内存也增加10倍；但真实运行总内存不一定严格按这个比例增长。')
note(74,'拿一把两格宽的尺子，比较每对相邻高度：后一个减前一个。每次往右挪一格，就能找出局部上升或下降。','核[-1,1]作用在窗口[a,b]上就是-a+b。这里不翻转核，是互相关，很多深度学习框架也用这种形式命名卷积。长度4、窗口2、步幅1、不补边，输出3项。','窗口[1,3]给2；[3,2]给-1；[2,5]给3，结果[2,-1,3]。正数表示局部上升，负数表示下降。','把核换成[0.5,0.5]，它变成局部平均。相同输入、不同小核就提取不同模式。')
note(75,'两个人各画一个框圈住物体，不能只看框大不大，还要看重叠部分占它们合起来覆盖区域的多少。','xyxy格式是左、上、右、下的坐标。交集宽取较小右边界减较大左边界，负数截为0；高度同理。并集=两面积之和−交集，避免重叠被算两次。','框A面积2×2=4，B也4。重叠是从(1,1)到(2,2)，面积1。并集4+4−1=7，IoU=1/7≈0.1429。','把B改成与A完全相同，交并集都4，IoU=1；完全分开则交集0，IoU=0。')
note(76,'把图片切成小方块，像把一张大拼图分成许多片。视觉Transformer可以把这些片分别表示成序列中的元素。','224除以16等于14，因此每行14块，每列14块。块数是两者相乘，不是相加。这里只计算无重叠、整齐切分的patch数，不调用模型。','横向14、纵向14，14×14=196。某些模型还加入额外特殊token，那是后续架构约定，不属于这196块图像本身。','把patch改成32，每边7块，总49。块变大后数量变少，但每块包含更多内容，精细信息的处理方式也改变。')
note(77,'把一句话里每个词出现了几次写下来，可以得到一份简单清单。词袋模型先不管先后顺序。','split按空白分词；Counter累计同样文字的次数。英文空格例子适合演示，中文往往不能只按空格切开。sorted让显示顺序稳定，不代表语言顺序。','ai learns ai分成[ai,learns,ai]；ai出现2次，learns出现1次。若换成ai ai learns，计数不变，说明此表示丢掉了词序。','写两句词序不同、含义不同却词频相同的短句，想一想只用词频的模型为何无法区分它们。')
note(78,'你读一句话时会保留对前面内容的简略记忆，后面的词再修改这份记忆。一个循环状态是这种想法的极简数学演示。','h从0开始，每次用新输入x加上0.5倍旧h，再经过tanh。tanh把数压在-1到1之间。代码中的赋值会覆盖h，因此下一步用的是刚更新后的状态。','第一步输入1，h=tanh(1)≈0.7616；第二步输入0，h=tanh(0.3808)≈0.3634；第三步输入-1，h=tanh(-0.8183)≈-0.6741，具体以运行输出为准。','把输入顺序反过来，最终状态通常不同。平均值不变却状态改变，说明递归能够保留某些顺序影响。')
note(79,'把一段声音每秒记录16000个数，32000个数就够记录两秒。采样率像每秒拍多少张快照，只是音频记录的是幅度。','样本数除以每秒样本数，单位会约掉“样本”，剩“秒”。单声道与双声道、每个样本占多少字节，是另外的存储问题。','32000样本÷16000样本/秒=2秒。代码输出2.0，因为Python的/运算通常返回浮点数。','样本数不变而把播放采样率改为8000，会改变播放时长和声音；正确重采样不能只是改一个标签。')
note(80,'先给积木编号，才能用编号查到对应积木。token ID只是约定好的索引，并不是词义大小。','本例手工规定学→0、习→1、AI→2。每次读取词表字典并组成列表。真实分词器会决定怎样切开文本，本例直接给定token列表，没有完成真实中文分词。','输入三个token，依次查vocab，得到[0,1,2]。编号2不表示AI比学习“更大”或“更聪明”，只是一个地址。','交换词表编号后，编码会变化，但需要把后续嵌入表一起匹配。不能给已训练模型随意换一份编号表。')
note(81,'你拿着“我想找什么”的查询卡，比较两张资料卡。越匹配的卡分到更大的权重，再把两张卡携带的数值按权重混合。','Q与每个K点积后除以√2，再通过softmax变成和为1的权重。V是被汇总的值，不必与匹配分数相同。Q/K用于找关系，V用于提供内容。','点积是[1,0]，缩放成[约0.7071,0]。softmax权重约[0.6698,0.3302]；汇总10×0.6698+20×0.3302≈13.3024，具体末位以运行结果为准。','把values换成[100,200]，权重不变、汇总扩大10倍。它能帮助区分“怎样分配”与“实际汇总了什么”。')
note(82,'做填空题时，只允许看当前位置以前的文字，不能提前看后面的标准答案。因果掩码就是一张“谁可以看谁”的表。','每一行表示当前查询位置i，每一列表示候选位置j。本例j≤i就写1，代表可见。这里只画可见性，不是实际给注意力得分乘0/1的唯一实现方式。','长度4：第一行只能看第1项[1,0,0,0]；第二行看前2项[1,1,0,0]；第三行前3项；第四行全部4项，形成下三角。','把条件改成j<i，当前位置自己也不可见。不同任务的mask规则必须明确，不能只记“都是三角形”。')
note(83,'一句话的每个位置都可以变成一道小题：看到前面这些内容，下一个是什么？训练不需要为每个位置另请人写答案。','for中的i是前缀结束位置，不包含该位置本身。seq[:i]作为输入，seq[i]作为目标，两者刚好分开。真实模型预测的是词表上一个分布，不是直接记住这里四个数字。','[2]→4；[2,4]→6；[2,4,6]→8。共有3题。输入如果把目标也放进去，就会让训练像偷看答案。','把序列改成短字符列表，亲手列出前缀与下一字符，理解训练目标来自哪里。')
note(84,'同样的候选排名，可以决定更坚持最高分，还是给其他候选更多机会。温度改变的是这种选择倾向。','先把分数除以温度，再softmax。T=0.5会把差距放大，T=2把差距缩小。没有改变候选文字本身，也没有增加事实证据。','分数[0,1]：T=0.5相当于[0,2]，第二项概率约0.8808；T=2相当于[0,0.5]，约0.6225。高温更平缓，但两种都仍偏向第二项。','先把所有分数设成一样，再调温度，分布仍均匀。这说明温度是在调整已有差距，而不是凭空制造知识。')
note(85,'一次演示回答漂亮，像只看到学生做对一道题。要评估能力，需要提前准备一组有明确判分规则的题。','True表示这道题按规则成功，False表示失败。sum会把True计为1、False计为0，再除以样例数。这个分数只属于这份测试和这套标准。','[True,False,True,True,False]有3次成功、共5次，所以3/5=0.6。不要把它解释为“任何问题都有60%正确概率”。','给每次失败加上类型，例如事实错、格式错、工具失败。一个总成功率之外，失败分布更能告诉你下一步该修哪里。')
note(86,'把两个不同的数挤进一个格子，只存它们的平均值，之后无法完整知道原来分别是什么。这是压缩信息损失的一个例子。','编码把[2,4]变成一个数3；解码简单复制成[3,3]。这里没有学习编码器，也不是完整VAE，只展示瓶颈表示与重建之间的关系。','原与重建差为[-1,1]，平方为[1,1]，总和2.0。本题算总平方误差，不是除以2后的均方误差。','对[3,3]使用同样方式，误差为0。压缩规则可能对某些数据无损、对其他数据有损，不能只看一个成功例子。')
note(87,'把清晰信号逐渐掺入噪声，像把一滴墨逐渐混入水里。前向加噪的规则已知，但从混合结果恢复原物是另一项需要学习的问题。','ᾱ控制保留信号的程度。两个系数是平方根，不是直接用0.8和0.2；这种选择与方差控制有关。本例只有一个数，不能生成图像。','√0.8约0.8944，乘原信号2约1.7889；√0.2约0.4472，乘噪声-1约-0.4472；相加约1.3416。','把α改成1，噪声系数0，结果回到原信号；改成0，结果只剩噪声。先用这两个端点检查公式。')
note(88,'你有三个标签的匹配分数，先找最大分数的位置，再根据位置取标签。这个过程与真正从图片提取分数是两回事。','labels与scores必须同顺序配对。max(range(...),key=...)不是直接返回最大分数，而是返回最大分数所在的索引。','分数[0.2,0.9,0.4]最大0.9，位置索引1；labels[1]是汽车。这里的分数人为给定，没有模型真的看过图片。','交换标签顺序却不交换分数，会得到错误含义。数据管道中保持索引对应，常比公式本身更容易出错。')
note(89,'今天得到1分，明天2分，后天3分。你可能更看重及时反馈，于是把越远的奖励乘更小系数，这叫折扣。','enumerate从0开始编号，因此第一项乘γ⁰=1，第二项γ¹，第三项γ²。折扣从当前位置算，不是每个奖励都只乘一次γ。','1×1+2×0.5+3×0.25=1+1+0.75=2.75。它比不折扣总和6小，但不是说未来奖励没有价值。','把gamma改成1，总回报变6；改成0，只剩第一个奖励1。它们是理解折扣的两个端点。')
note(90,'你原以为一个动作值1分，新线索让你觉得它应该值4.7分。没必要一次完全推翻旧估计，可以只吸收10%的差距。','目标=当前奖励+折扣后的下一状态最佳价值。更新=旧Q+学习率×(目标−旧Q)。方括号里的差是新证据与旧估计的差，不是最终价值。','目标2+0.9×3=4.7；差4.7−1=3.7；吸收0.1×3.7=0.37；新Q=1.37。','把alpha改成1，就完全替换为目标4.7；改成0则不更新。下一状态终止时，应另按终止规则处理后续价值。')
note(91,'你有25%机会选择奖励1的动作、75%机会选择奖励3的动作。长期平均收益需要按选择比例加权。','策略给出动作概率，它们应非负且加起来1。期望是“概率×奖励”的总和，不是把两个奖励简单平均。本题把奖励当作已知常数。','0.25×1=0.25，0.75×3=2.25，相加2.5。一次行动只会得到1或3，并不会真的得到2.5。','把概率换成[0.5,0.5]，期望2；再换成[0,1]，期望3。现实学习中不一定事先知道每个动作的真实奖励。')
note(92,'把一本长书切成可检索的小纸条，纸条边缘留一点重叠，减少一句话刚好被截断的问题。','块长4、重叠1意味着下一个起点前进4−1=3。切片超出末尾会自动停止，因此最后块可能短。这里按字符，不按真实模型token。','ABCDEFGHIJ：起点0取ABCD；3取DEFG；6取GHIJ；9取J。D和G出现在相邻块中，最后J也可能重复。','把overlap改为0，起点每次前进4；如果overlap等于size，步长变0不合法，必须提前检查。')
note(93,'两位老师给文章排了名次，但打分尺度不同。直接比较原分数不方便，可以先把名次变成可加的贡献。','RRF对每份排名计算1/(60+名次)，再相加。名次越前贡献越大。60是平滑常数，不是文档数量；这里只融合两份给定排名。','A贡献1/61+1/63，B是1/62+1/61，C是1/63+1/62。B大于A，A大于C，所以顺序B、A、C。','对一份排名中的同一文档换个名次，观察融合是否改变。文档没进入候选时需要另行规定其贡献，不能随意填一个有利名次。')
note(94,'书架上真正相关的资料有3篇，你找回2篇。即使找回的都很好，仍漏掉了三分之一证据。','集合交集找出既相关又被返回的文档。Recall@k分母是全部相关文档，不是返回数量。它回答找全程度，不回答返回结果是否都精准。','相关{A,C,F}，返回[A,B,C]；交集{A,C}有2篇；2/3≈0.6667。B无关会影响精确率，但不会直接增加召回分子。','把返回改为[A,C,F,B]，召回1.0，但还有无关B。因此评估时最好同时看多个指标。')
note(95,'让人按表格填答案比随意写一大段更方便核对，但表格填满也可能填错。结构化输出与事实正确是两层检验。','json.loads把JSON文字解析成字典。随后检查label属于允许集合，以及score在0到1范围。本例只检查这两条，不包含完整schema或事实核验。','label=positive在允许集合中；0≤0.8≤1也成立；两个条件用and连接，都为真，所以valid=True。','把score改成1.2，JSON仍能解析，但语义校验变False。请分清“格式能读”与“值符合规则”。')
note(96,'工具注册表像前台菜单：只能点已列出的菜，不能让顾客一句话就获得厨房所有设备的控制权。','字典tools把允许的名字add映射到函数。request提供名字与参数；**把字典中的a、b按名称传入函数。这个**出现在调用位置时是展开参数，不是乘方。','先找tools["add"]得到add_numbers；取arguments得到{a:2,b:3}；调用相当于add_numbers(a=2,b=3)，结果5。','把工具名改成没有登记的delete，当前程序会找不到键。正式接口应返回受控错误，而不是执行任意字符串。')
note(97,'做菜有读取菜谱、准备、烹饪、完成四步，但只给三步预算，就应停下来报告未完成，而不是偷偷宣布成功。','states[:max_steps]取允许执行的前三项。len(states)>max_steps检查是否还有剩余。这里没有真实Agent推理，只有一个确定的步骤预算演示。','四个状态长度4，预算3，截取得到读取问题、检索、验证证据。因为4>3，剩余判断True，说明完成这一状态还没有执行。','把预算改成4，剩余判断False。真实任务还需要明确成功条件，不能因为步数够了就自动认定结果正确。')
note(98,'比较两个回答时，人可以指出哪个更好，但这种偏好不一定代表其中一个完全正确。','chosen与rejected表示同一问题中的偏好回答与较差回答。当前打分器应给chosen更高分。zip必须逐对对齐，再统计满足大于关系的数量。','0.8>0.3为真，0.4>0.6为假，0.7>0.2为真，共2/3≈0.6667。第二对说明当前打分器没有符合这条偏好。','把一对两边分数设成相等，本题按严格>视为未正确排序。实际评估是否给半分，需要事先约定。')
note(99,'一张1000×1000的大表要存100万个数。如果改动可以由两个很薄的表相乘表达，只需要较少的新数。','原矩阵m×n有mn个参数；低秩因子B为m×r、A为r×n，总mr+rn=r(m+n)。这些是增量参数，基座大矩阵仍然存在。','原1000×1000=1,000,000；r=8时，1000×8+8×1000=16,000。可训练增量减少很多，但不能说整个模型只有16,000个参数。','把r改成16，因子参数变32,000。秩增加可能提升表达能力，也会增加训练成本，效果需要验证。')
note(100,'把每个长度只记录到最近的0.1刻度，可以少用一些表示精度，但原来0.12与0.10就会被记成同一档附近。','先用x/scale换成刻度个数，再舍入成整数q。恢复时乘回scale，得到近似原值。本例没有实现整数范围裁剪、零点偏移或完整模型量化。','0.12/0.1=1.2→1→0.1；0.47/0.1=4.7→5→0.5；-0.33/0.1=-3.3→-3→-0.3。误差来自舍入。','把scale变成0.01，重建更接近原值，但所需整数范围也可能变大。不能只追求小刻度而忽略位数限制。')
note(101,'推荐三本书，其中两本真合用户兴趣，前3项的精确率就是2/3。没推荐的其他好书不进入这个分母。','Precision@k只看前k项中有多少相关。这里所有推荐恰好3项。它与前面检索召回的区别仍是分母：推荐数量，而不是全部喜欢的物品数量。','推荐A、B、C，喜欢A、C、D；命中A、C两项，共3个推荐，所以2/3≈0.6667。未推荐的D体现遗漏，但不直接改变Precision@3。','把推荐改成A、C、D，三项都相关，精确率1.0。现实推荐还要考虑用户是否已经看过、物品是否可用等约束。')
note(102,'一个人问邻居平均有多少信息，再据此更新自己的看法。图神经网络的消息聚合可以从这个简化动作理解。','features按节点编号存数，neighbors存各节点相连的邻居编号。对每个节点，先读取邻居的旧值，再求平均；不能边更新边让后面节点读到新值。','节点0只看节点1的值3；节点1看节点0、2的值1、5，平均3；节点2只看节点1，也3。一次聚合结果[3,3,3]。','把中间节点的值改为9，两端都会受到影响；再思考为什么多次平均可能让不同节点越来越难区分。')
note(103,'预测明天时只能看今天和以前，不能把明天自己的数放进平均。这比选择多高级模型更基本。','t=3时预测第4项，用series[0:3]；t=4时预测第5项，用series[1:4]。结束位置不包含当前要预测的项。','预测第4项：(10+12+14)/3=12；预测第5项：(12+14+16)/3=14，结果[12.0,14.0]。它们比真实16、18偏低，因为序列在上升。','把序列改成常数，移动平均就能很好预测。模型表现取决于数据结构，不能只凭一种序列断言方法优劣。')
note(104,'找最少经过几条路到终点，可以先看离起点一条路的地方，再看两条路的地方。BFS就是按圈层向外找。','队列先进先出，popleft取最早入队的节点。seen记录已经发现的节点，避免环绕重复。distance表示用了几条边，而不是实际公里数。','从A距离0开始；把B、C以距离1入队。取B后发现D，距离2。之后取C，再取D时输出2并停止。','给图增加C→D，最少仍2；如果每条路花费不同，最少边数就不一定等于最低成本，需要换合适算法。')
note(105,'旅行时既要看已经花的钱，也要估计后面还需花多少。只看“离目标似乎很近”可能忽略已付出的巨大代价。','A*优先级f由已知成本g与估计剩余h相加。本页只选择下一候选，不执行完整搜索，也不验证启发式是否满足最优性条件。','A的f=2+5=7，B为4+1=5，C为3+3=6，最小是B。B的g并不最小，但综合估计最便宜。','把B的h改成10，优先选择会变化。任意高估剩余成本可能影响最优保证，启发式需要有依据。')
note(106,'排班时，你可能要求两个人总共值5小时，并且第一个人比第二个人少。先写条件，再找所有满足条件的组合。','两个for尝试所有x和y，各从0到5。if过滤同时满足x+y==5和x<y的组合。==检查相等，与赋值=不同。','x=0时y=5满足；x=1时y=4满足；x=2时y=3满足；x=3时y=2虽然总和5，却不满足x<y，因此不收录。','把<换成<=，这组总和为奇数的例子不会出现相等对；再把总和改成6，观察(3,3)的边界差异。')
note(107,'四次请求很快、一次极慢，平均值可能让你忽略那一次的等待体验。尾部分位数专门观察较慢的一端。','最近秩法先排序，再取第ceil(p×N)个，数学序号从1开始，因此Python索引要减1。小样本的分位数很粗，不代表稳定的线上估计。','N=5，p=0.95，pN=4.75，ceil得到5，索引4，对应100。因此p95是100，不是对95和100做插值。','把最慢值改成1000，平均与p95都会变。比较指标前必须确认采用的是哪种分位数定义。')
note(108,'实验记录像做菜时记下原料批次、配方和评分。只有“这次很好吃”无法让别人再做出同样结果。','字典里保存模型版本、数据版本和指标。json.dumps把它转成文本，sort_keys=True让各层字典按键排序，便于比较与保存。这里没有上传或连接实验平台。','run同时记录linear-v1、sample-v1和mse=0.1。若只换数据而模型名字不变，实验已经不是同一个条件；三项信息都值得保留。','增加一个learning_rate字段，再输出JSON。真实项目还应记录代码版本、随机种子和评价协议。')
note(109,'准备公开一张表时，最好先列“允许公开哪些列”，而不是只删掉自己碰巧想到的敏感列。','allowed是字段允许列表。字典推导式遍历原记录，仅当键在allowed中才保留。它不证明剩下信息已完全匿名，只是一个可检查的数据最小化步骤。','原记录有name、email、score。仅score在允许集合，因此结果{"score":0.8}，其他字段不进入输出。','在原记录增加phone字段，允许列表不变时它仍不会被保留。这体现允许列表对未知新字段的保守行为。')
note(110,'比较新旧学习方法最好让它们面对同样的三场考试，然后每场先求差，再看平均，而不是各挑自己最好的一次。','zip按运行编号配对。新分数减旧分数，正数表示这次提高，负数表示这次下降。平均差不自动提供统计显著性结论。','三次差分别0.03、-0.01、0.04，总0.06，平均0.02。不是每次都提高，但平均在这三次中为正。','把最好的那一次删掉，结果会变化。为什么保留所有预先规定的运行，而不是只汇报有利结果，是实验诚实性的核心。')
note(111,'毕业项目像一份交付清单：有基线、有独立测试，还要有错误分析。缺一项就说明还有明确工作没有完成。','all检查所有值是否都为True。列表推导式用if not v找出False对应的键。两者配合，一边给总体状态，一边给具体下一步。','baseline和independent_test为真，error_analysis为假，所以all返回False；未完成项列表只有error_analysis。','把最后一项改成True，结果变全部完成且空列表。实际验收时，每个True都应有证据，不是靠主观勾选。')

# Explain real syntax, not guessed intent; values are observed from the authored example.
def short(text,n=90):
    text=str(text)
    return text if len(text)<=n else text[:n]+'…'
def source(node): return ast.unparse(node)
def expr(node):
    if isinstance(node,ast.Constant):
        if isinstance(node.value,str): return '文字'+repr(node.value)
        if node.value is None:return '表示缺失或无返回结果的None'
        return '值'+repr(node.value)
    if isinstance(node,ast.Name):return '从名字“'+node.id+'”取出当前值'
    if isinstance(node,ast.List):return '按顺序准备列表'+short(source(node),70)+'（逗号分开各项）'
    if isinstance(node,ast.Tuple):return '按顺序准备这一组值'+short(source(node),70)
    if isinstance(node,ast.Dict):return '建立键与值的对应表'+short(source(node),70)
    if isinstance(node,ast.BinOp):
        symbols={ast.Add:('相加','+'),ast.Sub:('相减','-'),ast.Mult:('相乘','*'),ast.Div:('相除','/'),ast.Pow:('乘方','**'),ast.FloorDiv:('整除并向下取整','//'),ast.Mod:('取余数','%')}
        action,symbol=symbols.get(type(node.op),('运算',''))
        return f'先计算左右两部分，再将“{short(source(node.left),35)}”与“{short(source(node.right),35)}”{action}；{symbol}在这里采用Python的运算规则'
    if isinstance(node,(ast.ListComp,ast.GeneratorExp,ast.SetComp,ast.DictComp)):
        gen=node.generators[0]
        item=source(node.elt) if hasattr(node,'elt') else source(node.value)
        filt='；只有'+source(gen.ifs[0])+'成立时才处理' if gen.ifs else ''
        return f'依次从{short(source(gen.iter),45)}取一项，暂时叫{source(gen.target)}{filt}，每项按{short(item,55)}计算'+('；用方括号收集成新列表' if isinstance(node,ast.ListComp) else '；把结果逐项交给外层操作')
    if isinstance(node,ast.Subscript):
        if isinstance(node.slice,ast.Slice):return '从'+source(node.value)+'按切片'+source(node.slice)+'取出一段，结束位置不包含在内，原数据不会因此被删除'
        return '从'+source(node.value)+'中按'+source(node.slice)+'取对应项；列表按位置编号，字典按键名查找'
    if isinstance(node,ast.Compare):return '检查条件“'+source(node)+'”是否成立，结果是True或False，而不是直接改变变量'
    if isinstance(node,ast.Call):
        name=source(node.func);args=[source(a) for a in node.args];first=short(args[0],70) if args else '输入'
        common={
            'print':'先算好括号里各项，再显示到运行结果；多个参数默认用空格分隔，显示不等于return',
            'sum':'把'+first+'里的数逐个加起来，得到总和',
            'len':'数一数'+first+'中有多少项，返回数量，不是最后一个索引',
            'round':'对'+first+'做舍入'+('，小数位数取'+args[1] if len(args)>1 else '，默认舍入到整数')+'；它不是强制补齐末尾0的显示格式',
            'type':'查看输入当前属于哪种数据类型，.__name__可取类型的简短名称',
            'int':'尝试把'+first+'转换为整数；不符合整数格式的文字会报错',
            'float':'尝试把'+first+'转换为浮点数，方便进行含小数的计算',
            'input':'显示提示并读取一行文字；即使输入看起来像数字，得到的仍先是字符串',
            'range':'生成一串有规则的整数'+short('('+','.join(args)+')',50)+'；停止值不包含在内，第三个参数（若有）是步长',
            'abs':'取'+first+'的绝对值，只保留离0的大小，不保留正负方向',
            'max':'按指定比较规则挑出最大的值；如果带key，会先按key计算比较依据',
            'min':'按指定比较规则挑出最小的值；如果带key，返回的是原候选，不是比较分数',
            'list':'把可逐项读取的结果收集成一个列表；这可能会消耗一次性生成器',
            'set':'将输入收集成不重复的元素集合，不能依赖它保持原位置顺序',
            'sorted':'先产生一个按规则排序的新列表；原容器本身通常不会被修改',
            'zip':'把各组数据在相同位置的项配成一组；长度不等时默认按较短的一方结束',
            'enumerate':'读取数据时同时给出编号，默认从0开始',
            'all':'检查所有值是否都成立；只要有一个为False，就得到False',
            'math.sqrt':'计算'+first+'的非负平方根：寻找平方后等于它的非负数',
            'math.exp':'计算e的'+first+'次方；e约为2.718，不是把输入直接乘e',
            'math.log':'计算'+first+'的对数；未指定底数时用自然对数',
            'math.log2':'计算以2为底的对数，常用于以比特计的信息量',
            'math.ceil':'将'+first+'向上取整；有不足一份的尾数也要占完整一份',
            'math.tanh':'对'+first+'应用双曲正切，把结果映到-1与1之间',
            'math.isclose':'按容差判断两个浮点数是否足够接近，而不是要求逐值严格相等',
            'json.loads':'把符合JSON格式的文字解析回Python对象，便于按键读取',
            'json.load':'从已经打开的文件读取JSON，并解析为Python对象',
            'json.dump':'把Python对象写成JSON到指定文件；本网站文件位于临时虚拟系统',
            'json.dumps':'把Python对象转换成JSON文字，返回字符串而不是自动保存文件',
        }
        if name in common:return common[name]
        if name.endswith('.append'):return '把新的一项加到列表末尾，直接修改原列表；此操作本身返回None'
        if name.endswith('.get'):return '按键查找字典；如果给了默认值，找不到键时返回该默认值'
        if name.endswith('.strip'):return '去掉文字两端的空白，返回新字符串，中间空格不会因此全被删除'
        if name.endswith('.split'):return '按指定分隔符切开文字；不传分隔符时按空白拆分，返回片段列表'
        if name.endswith('.items'):return '逐个读取字典中的键和值，便于一起处理'
        if name.endswith('.popleft'):return '从队列最左端取出并移除最早放入的一项'
        if name.endswith('.intersection'):return '找出同时出现在两组集合中的元素'
        if name.endswith('.count'):return '统计输入值在容器中出现多少次'
        if name=='open':return '按指定文件名和模式打开文件；w写入可能覆盖原内容，读取模式用于取回文字'
        return f'调用工具“{name}”，把括号里的输入交给它，再使用它返回的结果；先理解本页对该工具的定义，不必一次记住所有接口'
    if isinstance(node,ast.Attribute):return '读取'+source(node.value)+'上的属性或方法“'+node.attr+'”'
    if isinstance(node,ast.IfExp):return '先判断'+source(node.test)+'，成立时取'+source(node.body)+'，否则取'+source(node.orelse)
    return '按代码规则计算“'+short(source(node),110)+'”；可以先把复杂部分单独打印来检查'

def annotation(node):
    if isinstance(node,ast.Assign):
        target='、'.join(source(t) for t in node.targets)
        return '把结果交给 '+target,expr(node.value)+'。最后把右边结果交给左边名字。若左边有多个名字，就按顺序一一对应。'
    if isinstance(node,ast.AugAssign):
        op={ast.Add:'加上',ast.Sub:'减去',ast.Mult:'乘上',ast.Div:'除以'}.get(type(node.op),'按规则合并')
        return '更新 '+source(node.target),'先取出旧值，再'+op+source(node.value)+'，把新结果存回同一名字；下一次循环将使用更新后的值。'
    if isinstance(node,ast.For):return '开始逐项重复','从'+short(source(node.iter),85)+'依次取值，当前值命名为'+source(node.target)+'；下面缩进的代码对每一项执行一次。'
    if isinstance(node,ast.While):return '按条件重复','每次执行前检查'+source(node.test)+'；成立就执行缩进块，再回来检查。条件一直不变时可能无限循环。'
    if isinstance(node,ast.If):return '决定是否走这一条分支','先计算'+source(node.test)+'的真假，再执行对应缩进块。退回原缩进表示离开分支。'
    if isinstance(node,ast.FunctionDef):return '定义一个可复用工具','工具名是'+node.name+'，输入名字是'+('、'.join(a.arg for a in node.args.args) or '无显式参数')+'。这时主要是在登记规则，真正调用时才执行内部步骤。'
    if isinstance(node,ast.ClassDef):return '定义一种对象','类名是'+node.name+'。它描述对象会保存什么状态、提供哪些方法；创建实例后才拥有某一份具体状态。'
    if isinstance(node,ast.Return):return '把结果交回调用者',('先计算'+source(node.value)+'，再结束当前函数并把结果交出去。' if node.value else '结束函数，返回None。')+'return负责交回，不负责把结果显示在屏幕上。'
    if isinstance(node,(ast.Import,ast.ImportFrom)):return '准备工具箱','导入'+', '.join(a.name for a in node.names)+'供后面的代码使用。仅导入不等于完成模型训练，也不必然产生输出。'
    if isinstance(node,ast.Expr):return '执行一个操作',expr(node.value)+'。'
    if isinstance(node,ast.With):return '进入会自动收尾的操作块','打开或准备资源后执行缩进块；离开这个块时自动完成相应清理。文件例子中用于确保关闭文件。'
    if isinstance(node,ast.Try):return '准备尝试可能失败的操作','先执行try的缩进块。如果出现匹配的异常，再走except备用流程；不是忽略所有错误。'
    if isinstance(node,ast.ExceptHandler):return '处理特定失败','只处理这里声明的错误类型。备用结果应该符合业务含义，不能为了不报错而掩盖数据问题。'
    if isinstance(node,ast.Assert):return '检查一个预期是否成立','计算'+source(node.test)+'。成立则继续，不成立抛出AssertionError，帮助发现行为不符合预期。'
    if isinstance(node,ast.Break):return '提前离开当前循环','直接结束最近一层循环，而不是结束整份程序。退出后从循环后面的代码继续。'
    return '执行本行','先按本页给出的数据理解这行，再运行对照结果。'

def code_notes(code):
    tree=ast.parse(code)
    nodes={}
    kinds=(ast.Assign,ast.AugAssign,ast.For,ast.While,ast.If,ast.FunctionDef,ast.ClassDef,ast.Return,ast.Import,ast.ImportFrom,ast.Expr,ast.With,ast.Try,ast.ExceptHandler,ast.Assert,ast.Break)
    for n in ast.walk(tree):
        if isinstance(n,kinds) and getattr(n,'lineno',None) and n.lineno not in nodes:nodes[n.lineno]=n
    rows=[]
    for i,line in enumerate(code.splitlines(),1):
        if not line.strip():continue
        if line.lstrip().startswith('#'):title,explain='给人看的说明','这一行是注释，Python跳过它。你可以修改说明文字而不影响下面代码的计算。'
        elif i in nodes:title,explain=annotation(nodes[i])
        else:title,explain='接着上一行读','这一行属于前面还没有结束的表达式或代码块。结合括号和缩进把它作为一个整体阅读，不要把换行误认为一定是一个新操作。'
        substeps=[]
        if i in nodes:
            def visit(n):
                for child in ast.iter_child_nodes(n):visit(child)
                if getattr(n,'lineno',None)!=i:return
                if isinstance(n,(ast.Call,ast.ListComp,ast.GeneratorExp,ast.SetComp,ast.DictComp)):
                    label=source(n)
                    if isinstance(n,ast.Call) and source(n.func)=='print':return
                    if label not in [x['code'] for x in substeps]:substeps.append(dict(code=short(label,160),explain=expr(n)))
            visit(nodes[i])
        rows.append(dict(line=i,code=line,title=title,explain=explain,substeps=substeps[:8]))
    return rows

def safe_value(value,depth=0):
    if isinstance(value,(str,int,float,bool)) or value is None:
        return short(repr(value),130)
    if depth>1:return '…'
    if isinstance(value,(list,tuple)):
        return '['+', '.join(safe_value(v,depth+1) for v in value[:8])+(', …' if len(value)>8 else '')+']'
    if isinstance(value,dict):
        items=list(value.items())[:5]
        return '{'+', '.join(str(k)+': '+safe_value(v,depth+1) for k,v in items)+(', …' if len(value)>5 else '')+'}'
    if isinstance(value,set):return '{'+', '.join(sorted(map(str,value)))+'}'
    return '〈'+type(value).__name__+'对象〉'

def observe(code):
    output=io.StringIO();events=[];last={};previous=None
    def trace(frame,event,arg):
        nonlocal previous,last
        if frame.f_code.co_filename!='course_example.py' or frame.f_code.co_name!='<module>':return trace
        if event not in ('line','return'):return trace
        current={k:safe_value(v) for k,v in frame.f_locals.items() if not k.startswith('__') and k!='input' and not isinstance(v,(types.ModuleType,types.FunctionType,type))}
        current={k:v for k,v in current.items() if v is not None}
        changes={k:v for k,v in current.items() if last.get(k)!=v}
        if previous is not None and changes:events.append(dict(line=previous,values=changes))
        last=current;previous=frame.f_lineno
        return trace
    import os,tempfile
    cwd=os.getcwd()
    with tempfile.TemporaryDirectory(dir='/tmp') as d:
        try:
            os.chdir(d);sys.settrace(trace)
            with contextlib.redirect_stdout(output):exec(compile(code,'course_example.py','exec'),{'input':lambda prompt='':'15'})
        finally:sys.settrace(None);os.chdir(cwd)
    total=len(events)
    selected=events if total<=14 else events[:10]+events[-4:]
    return dict(output=output.getvalue().strip(),events=selected,total=total,omitted=max(0,total-len(selected)))

# Local SVG illustrations. All labels and numerical marks correspond to authored examples.
def tx(x,y,value,size=24,anchor='start',color='#273749'):
    return f'<text x="{x}" y="{y}" font-size="{size}" text-anchor="{anchor}" fill="{color}">{html.escape(str(value))}</text>'
def line(x1,y1,x2,y2,color='#64748b',width=3,arrow=False):
    return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{color}" stroke-width="{width}"'+(' marker-end="url(#arrow)"' if arrow else '')+'/>'
def rect(x,y,w,h,fill='#f4f7fb',stroke='#b8c6d6',radius=5):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{radius}" fill="{fill}" stroke="{stroke}" stroke-width="2"/>'
def circle(x,y,r,fill='#2563eb'):return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{fill}"/>'
def wrap(value,units=42):
    out=[];cur='';n=0
    for c in str(value):
        u=2 if ord(c)>255 else 1
        if n+u>units:out.append(cur);cur='';n=0
        cur+=c;n+=u
    if cur:out.append(cur)
    return out

def textblock(x,y,value,units=46,size=24,lines=3,color='#273749',anchor='start'):
    rows=wrap(short(value,150),units)
    if len(rows)>lines:
        rows=rows[:lines];rows[-1]=rows[-1][:-1]+'…'
    return ''.join(tx(x,y+j*(size+10),v,size,anchor,color) for j,v in enumerate(rows))
def svg_doc(title,inner,height=460,desc=''):
    return f'''<svg xmlns="http://www.w3.org/2000/svg" width="760" height="{height}" viewBox="0 0 760 {height}" role="img" aria-labelledby="title desc"><title id="title">{html.escape(title)}</title><desc id="desc">{html.escape(desc)}</desc><defs><marker id="arrow" markerWidth="10" markerHeight="10" refX="8" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8" fill="none" stroke="#64748b" stroke-width="1.5"/></marker></defs><rect width="760" height="{height}" fill="white"/><g font-family="PingFang SC,Microsoft YaHei,Arial,sans-serif">{tx(30,43,short(title,26),25)}{inner}</g></svg>'''

def pipeline(l,observed):
    tree=ast.parse(l['code']);given=[]
    for n in tree.body:
        if isinstance(n,ast.Assign):
            try:ast.literal_eval(n.value);given.append(short(ast.unparse(n),75))
            except (ValueError,TypeError):pass
    inp='；'.join(given[:2]) or ('标准输入：15' if l['id']==3 else '按本页给定代码与数据开始')
    process=NOTES[l['id']]['explanation'].split('。')[0]
    out=observed['output'].replace('\n','；')
    inner=''
    for y,label,body,color in [(80,'① 输入：先准备这些信息',inp,'#eff6ff'),(250,'② 操作：按这条规则处理',process,'#f3f6fb'),(420,'③ 输出：实际运行得到',out,'#edf8f1')]:
        inner+=rect(30,y,700,140,color)+tx(50,y+35,label,24)+textblock(50,y+77,body,units=54,size=23,lines=2)
    inner+=line(380,222,380,246,arrow=True)+line(380,392,380,416,arrow=True)
    return svg_doc(l['title']+'：输入怎样变成结果',inner,590,'从上到下阅读。上框给出当前示例输入，中框是计算规则，下框是实际执行结果。'), '从上到下读：先找到输入，再看中间的操作，最后对照实际输出。图中的值来自本页示例；长内容会省略，完整输出见后面的示例记录。这不是完整工程系统。'


def table_picture(title,headers,rows,conclusion):
    width=680/len(headers);height=160+len(rows)*68+110;inner=''
    for c,h in enumerate(headers):inner+=rect(40+c*width,80,width,58,'#e7effb')+tx(55+c*width,117,h,24)
    for r,row in enumerate(rows):
        for c,v in enumerate(row):inner+=rect(40+c*width,138+r*68,width,68,'#ffffff')+textblock(55+c*width,177+r*68,str(v),units=max(12,int((width-28)/13)),size=24,lines=1)
    inner+=textblock(40,height-55,conclusion,units=54,size=24,lines=2)
    return svg_doc(title,inner,height,conclusion),conclusion

def bars_picture(title,labels,values,conclusion):
    height=150+max(3,len(values))*57+95;inner='';limit=max(abs(float(v)) for v in values) or 1
    negative=any(float(v)<0 for v in values);zero=420 if negative else 270;span=180 if negative else 300
    inner+=line(zero,80,zero,95+len(values)*57,'#bac6d2',2)
    for r,(label,v) in enumerate(zip(labels,values)):
        y=100+r*57;v=float(v);w=abs(v)/limit*span;x=zero-w if v<0 else zero
        inner+=tx(40,y+27,label,24)+rect(x,y,w if w else 2,36,'#e9a24d' if v<0 else '#78a9ed','#ffffff',2)
        label_text=str(round(v,4));inner+=tx(max(270,x+w+9),y+27,label_text,23)
    inner+=textblock(40,height-60,conclusion,units=54,size=24,lines=2)
    return svg_doc(title,inner,height,conclusion),conclusion

def additional_picture(l,obs):
    i=l['id']
